  light:     { id: "light",     dialogueRounds: 3,  priceYearly: null, label: "ライト" },
  standard:  { id: "standard",  dialogueRounds: 5,  priceYearly: null, label: "スタンダード" },
  supporter: { id: "supporter", dialogueRounds: 10, priceYearly: null, label: "サポーター" },
