const talkDelay = (i) => `${Math.min(i * 0.28, 8).toFixed(2)}s`;
const talkSkip = (e) => { try { e.currentTarget.classList.add("talk-all"); } catch (x) { /* 無視 */ } };
function TalkText({ text }) {
  const parts = String(text || "").replace(/([。！？!?])/g, "$1\n").split("\n").filter((x) => x.trim());
  /* ⚠️ 金の照り（sheen-text）は各行に付ける。親に付けると、子の透明度アニメで文字が消える */
  return parts.map((p, i) => <span key={i} className="sheen-text talk" style={{ animationDelay: talkDelay(i) }}>{p}</span>);
}
function ReadingBody({ text, anchorPrefix, highlight = -1, talk = false }) {
  const lines = String(text || "").split("\n");
  let headIdx = -1;
  const tk = (i) => (talk ? { animationDelay: talkDelay(i) } : undefined);
  return lines.map((line, i) => {
    if (line.startsWith("\u0001")) {
      const body = line.slice(1);
      const tab = body.indexOf("\t");
      // 区切り文字より前が色。無ければ既定の金のまま
      const color = tab > 0 ? body.slice(0, tab) : null;
      const text = tab > 0 ? body.slice(tab + 1) : body;
      headIdx++;
      const hit = anchorPrefix && headIdx === highlight;
      return (
        <span key={i}
          id={anchorPrefix ? `${anchorPrefix}-${headIdx}` : undefined}
          className={`reading-head${hit ? " reading-head-hit" : ""}${talk ? " talk" : ""}`}
          style={{ ...(color ? { color } : {}), ...(tk(i) || {}) }}>{text}</span>
      );
    }
    if (line.startsWith("\u0002") || line.startsWith("\u0003")) {
      const reversed = line.startsWith("\u0003");
      return (
        <span key={i} className={`reading-card-row${talk ? " talk" : ""}`} style={tk(i)}>
          <span className={`reading-card${reversed ? " rev" : ""}`}>{line.slice(1)}</span>
        </span>
      );
    }
    if (!line.trim()) return <span key={i} className="reading-gap" />;
    return <span key={i} className={`sheen-text reading-line${talk ? " talk" : ""}`} style={tk(i)}>{line}</span>;
  });
}
function NoteLines({ text }) {
  const lines = String(text || "")
    .replace(/([。！？])/g, "$1\n")
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);
  return lines.map((line, i) => (
    <span key={i} style={{ display: "block" }}>{line}</span>
  ));
}
