      <linearGradient id="zkGround1Claw" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF4DA" /><stop offset="0.5" stopColor="#E0C090" /><stop offset="1" stopColor="#8A6438" /></linearGradient>
