/* ================= 3. アリジゴク（b2） ================= */
function ZkGround3Defs() {
  return (
    <defs>
      <linearGradient id="zkGround3Shell" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D8AC78" /><stop offset="0.5" stopColor="#7A5030" /><stop offset="1" stopColor="#2A180A" /></linearGradient>
      <linearGradient id="zkGround3Jaw" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0CC" /><stop offset="0.45" stopColor="#C8945A" /><stop offset="1" stopColor="#4A2C12" /></linearGradient>
      <linearGradient id="zkGround3Head" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#B88A58" /><stop offset="1" stopColor="#3A2210" /></linearGradient>
    </defs>
  );
}
// 砂の渦（アリジゴクの巣）
function ZkGround3Pit({ cx, cy }) {
  return (
    <g transform={`translate(${cx} ${cy})`}>
      <ellipse rx="26" ry="4.6" fill="#E0C090" opacity="0.16" />
      <ellipse className="zk-ground-swirl" rx="25" ry="4.4" fill="none" stroke="#E0C090" strokeWidth="0.9" strokeDasharray="10 6" opacity="0.7" />
      <ellipse className="zk-ground-swirl" rx="16" ry="2.8" fill="none" stroke="#E0C090" strokeWidth="0.8" strokeDasharray="7 5" opacity="0.6" style={{ animationDelay: "-1s" }} />
      <ellipse className="zk-ground-swirl" rx="8" ry="1.4" fill="none" stroke="#FFE0A8" strokeWidth="0.7" strokeDasharray="4 3" opacity="0.6" style={{ animationDelay: "-2s" }} />
    </g>
  );
}
// 鎌の顎：先は -x、付け根が原点。上を向いて反る
