/* ================= 4. 土偶の番人（b2） ================= */
function ZkGround4Defs() {
  return (
    <defs>
      <linearGradient id="zkGround4Clay" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D8B088" /><stop offset="0.5" stopColor="#8A6240" /><stop offset="1" stopColor="#3A2616" /></linearGradient>
      <linearGradient id="zkGround4Goggle" x1="0" y1="0" x2="0.6" y2="1"><stop offset="0" stopColor="#E8C8A0" /><stop offset="1" stopColor="#6A4A2C" /></linearGradient>
      <linearGradient id="zkGround4Slit" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#FFB040" /><stop offset="0.5" stopColor="#FFF0B8" /><stop offset="1" stopColor="#FFB040" /></linearGradient>
    </defs>
  );
}
// 遮光器の目：中心が原点
function ZkGround4Eye({ rx, ry }) {
  return (
    <g>
      <ellipse rx={rx} ry={ry} fill="url(#zkGround4Goggle)" stroke="#3A2616" strokeWidth="0.6" />
      <ellipse rx={rx * 0.74} ry={ry * 0.66} fill="none" stroke="#5A3C22" strokeWidth="0.6" />
      <ellipse className="zk-blink" rx={rx * 0.8} ry={Math.max(0.7, ry * 0.2)} fill="url(#zkGround4Slit)" />
    </g>
  );
}
