function ZkGround5Defs() {
  return (
    <defs>
      <linearGradient id="zkGround5Hide" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#ECCB94" /><stop offset="0.45" stopColor="#A07040" /><stop offset="1" stopColor="#3A220E" /></linearGradient>
      <linearGradient id="zkGround5Lip" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#D8A878" /><stop offset="1" stopColor="#5A3418" /></linearGradient>
      <radialGradient id="zkGround5Maw"><stop offset="0" stopColor="#FFE9A8" /><stop offset="0.22" stopColor="#FF9A38" /><stop offset="0.55" stopColor="#5A200C" /><stop offset="1" stopColor="#1A0806" /></radialGradient>
      <linearGradient id="zkGround5Tooth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F6EAD0" /><stop offset="1" stopColor="#8A7458" /></linearGradient>
      <radialGradient id="zkGround5Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFD070" /><stop offset="1" stopColor="#FF9A30" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 石の歯が輪に並ぶ口：中心が原点
function ZkGround5Maw({ rx, ry, n = 12 }) {
  const p = (t, k) => `${(Math.cos(t) * rx * k).toFixed(1)} ${(Math.sin(t) * ry * k).toFixed(1)}`;
  const teeth = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2, d = (Math.PI / n) * 0.85;
    teeth.push(<path key={i} d={`M${p(a - d, 1)} L${p(a, 0.5)} L${p(a + d, 1)} Z`} fill="url(#zkGround5Tooth)" />);
  }
  return (
    <g>
      <ellipse rx={rx * 1.22} ry={ry * 1.16} fill="url(#zkGround5Lip)" />
      <ellipse rx={rx} ry={ry} fill="url(#zkGround5Maw)" />
      <g className="zk-glow"><ellipse rx={rx * 0.34} ry={ry * 0.34} fill="#FFE9A8" opacity="0.8" /></g>
      {teeth}
    </g>
  );
}
function ZkGround5Motes({ pts }) {
  return pts.map(([x, y, d, r], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r || 2.6} fill="url(#zkGround5Mote)" /></g></g>
  ));
}
