/* ======== 6. 岩山ゴーレム（b3）：積み重なる石板、継ぎ目が光る ======== */
function ZkRock6Defs() {
  return (
    <defs>
      <linearGradient id="zkRock6Stone" x1="0.1" y1="0" x2="0.9" y2="1"><stop offset="0" stopColor="#D4BC9C" /><stop offset="0.5" stopColor="#7E664C" /><stop offset="1" stopColor="#2E2418" /></linearGradient>
      <linearGradient id="zkRock6Dark" x1="0.1" y1="0" x2="0.9" y2="1"><stop offset="0" stopColor="#7A624A" /><stop offset="1" stopColor="#241A10" /></linearGradient>
      <radialGradient id="zkRock6Aura"><stop offset="0" stopColor="#FFB040" stopOpacity="0.5" /><stop offset="0.6" stopColor="#C8702A" stopOpacity="0.15" /><stop offset="1" stopColor="#C8702A" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkRock6Core"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFD890" /><stop offset="1" stopColor="#E8802A" /></radialGradient>
      <radialGradient id="zkRock6Mote"><stop offset="0" stopColor="#FFF0C8" /><stop offset="0.4" stopColor="#FFC060" /><stop offset="1" stopColor="#E8802A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 石板の群れ：各板の下に琥珀の継ぎ目（光）を敷いてから板を重ねる
function ZkRock6Slabs({ list, dark }) {
  return (
    <g>
      <g className="zk-shine">{list.map((d, i) => <path key={i} d={d} fill="none" stroke="#FFB040" strokeWidth="2.2" strokeLinejoin="round" opacity={dark ? 0.55 : 0.95} />)}</g>
      {list.map((d, i) => <path key={i} d={d} fill={dark ? "url(#zkRock6Dark)" : "url(#zkRock6Stone)"} />)}
    </g>
  );
}
function ZkRock6Motes({ list }) {
  return list.map(([x, y, d, s], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}>
      {s ? <path d="M-2 -1.6 L1.6 -2 L2.2 1.4 L-1.4 2 Z" fill="url(#zkRock6Stone)" /> : <circle r="2.4" fill="url(#zkRock6Mote)" />}
    </g></g>
  ));
}
