/* ---- zk:grass ---- */
// ZKT/grass.jsx — くさ（系統 earth）。緑は抑え、木肌の茶と琥珀の光で。
/* ================= 1. マンドラゴラ（叫ぶ根） ================= */
function ZkGrass1Defs() {
  return (
    <defs>
      <linearGradient id="zkGrass1Root" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#F2D6A6" /><stop offset="0.5" stopColor="#B8844E" /><stop offset="1" stopColor="#4E3018" /></linearGradient>
      <linearGradient id="zkGrass1Leaf" x1="0" y1="1" x2="0.3" y2="0"><stop offset="0" stopColor="#3A3818" /><stop offset="0.6" stopColor="#7E7634" /><stop offset="1" stopColor="#D0BC6A" /></linearGradient>
      <radialGradient id="zkGrass1Mouth" cx="0.5" cy="0.62"><stop offset="0" stopColor="#FFC860" /><stop offset="0.35" stopColor="#A8481A" /><stop offset="1" stopColor="#1E0A04" /></radialGradient>
    </defs>
  );
}
function ZkGrass1Lf({ a, l, w = 5 }) {
  return (
    <g transform={`rotate(${a})`}>
      <path d={`M0 0 C${-w} ${-l * 0.3} ${-w * 0.7} ${-l * 0.8} 0 ${-l} C${w * 0.7} ${-l * 0.8} ${w} ${-l * 0.3} 0 0 Z`} fill="url(#zkGrass1Leaf)" />
      <path d={`M0 -1 L0 ${-l * 0.85}`} stroke="#E0C090" strokeWidth="0.5" opacity="0.5" />
    </g>
  );
}
function ZkGrass1Scream({ x, y, s = 1, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-shine" style={{ animationDelay: `${d}ms` }}>
      <path d="M0 -5 Q-3 0 0 5 M-5 -9 Q-10 0 -5 9" fill="none" stroke="#FFD890" strokeWidth="1.1" strokeLinecap="round" opacity="0.8" />
    </g></g>
  );
}
function ZkGrass1S() {
  return (
    <g>
      <ZkGrass1Defs />
      <g className="zk-breathe"><g transform="rotate(-12 50 90)">
        {/* 奥の脚：後ろへ蹴る */}
        <path d="M56 74 C60 80 66 84 74 86 L73 90 C64 89 56 84 51 78 Z" fill="#6A4424" />
        {/* 奥の腕 */}
        <path d="M58 50 C66 50 72 46 76 40 L78 42 C74 50 66 56 58 56 Z" fill="#7A5230" />
        <path d="M77 41 L82 36 M77 41 L83 42" stroke="#7A5230" strokeWidth="1.1" strokeLinecap="round" />
        {/* 葉の房。⚠️ 揺れるのはここ */}
        <g transform="translate(50 31)"><g className="zk-flick">
          <ZkGrass1Lf a={80} l={20} /><ZkGrass1Lf a={54} l={25} w={6} /><ZkGrass1Lf a={28} l={23} /><ZkGrass1Lf a={4} l={16} w={4} />
        </g></g>
        {/* 胴（根の塊） */}
        <path d="M40 31 C30 36 27 50 31 62 C34 72 41 79 50 79 C59 79 65 70 65 58 C65 44 59 33 51 30 C47 29 43 29 40 31 Z" fill="url(#zkGrass1Root)" />
        <path d="M55 40 Q59 50 57 62 M46 67 Q52 71 58 67 M58 72 Q64 78 66 84 M62 64 Q70 66 74 72" fill="none" stroke="#5A3A1E" strokeWidth="0.8" opacity="0.6" strokeLinecap="round" />
        <path d="M42 33 Q50 37 58 33" fill="none" stroke="#E8C46A" strokeWidth="1.3" />
        {/* 手前の脚：前へ踏み出す */}
        <path d="M44 74 C40 80 34 85 26 88 L27 92 C36 90 44 86 50 78 Z" fill="url(#zkGrass1Root)" />
        {/* 手前の腕：前へ振り上げる */}
        <path d="M42 50 C36 48 30 44 24 38 L22 40 C27 46 33 52 40 55 Z" fill="url(#zkGrass1Root)" />
        <path d="M23 39 L16 36 M23 39 L17 42 M24 38 L21 31" stroke="#9A6A3A" strokeWidth="1.2" strokeLinecap="round" />
        {/* 叫ぶ口 */}
        <ellipse cx="35" cy="56" rx="5.2" ry="7.6" transform="rotate(-14 35 56)" fill="url(#zkGrass1Mouth)" stroke="#3A200C" strokeWidth="0.6" />
        {/* 目 */}
        <path className="zk-blink" d="M33 42 Q37 39 41 42 Q37 43.6 33 42 Z" fill="#FFD070" />
        <circle cx="36.4" cy="42" r="1" fill="#2A1404" />
        <path d="M32 38.4 L41.5 40.4" stroke="#3A200C" strokeWidth="1.1" strokeLinecap="round" />
        <path d="M38 34 Q44 31 50 32" fill="none" stroke="#FFE8C0" strokeWidth="1" opacity="0.6" strokeLinecap="round" />
      </g></g>
      <ZkGrass1Scream x={22} y={60} s={1.1} />
    </g>
  );
}
