/* ================= 4. 苔鹿（枝の角の鹿） ================= */
function ZkGrass4Defs() {
  return (
    <defs>
      <linearGradient id="zkGrass4Hide" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D2A472" /><stop offset="0.5" stopColor="#7E5430" /><stop offset="1" stopColor="#2E1C0E" /></linearGradient>
      <linearGradient id="zkGrass4Moss" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#B4AA5E" /><stop offset="1" stopColor="#4A4A1E" /></linearGradient>
    </defs>
  );
}
function ZkGrass4Moss({ x, y, l = 10, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y})`}><g className="zk-sway" style={{ animationDelay: `${d}ms` }}>
      <path d={`M-2.4 0 C-3 ${l * 0.4} -1.6 ${l * 0.7} -1 ${l} C0 ${l * 0.8} 0.6 ${l * 1.05} 1.4 ${l * 0.85} C2 ${l * 0.5} 3 ${l * 0.3} 2.4 0 Z`} fill="url(#zkGrass4Moss)" />
    </g></g>
  );
}
function ZkGrass4Antler({ d, w = 2.6, c = "#8A6440" }) {
  return (
    <g>
      <path d={d} fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
      <path d={d} fill="none" stroke="#E8C898" strokeWidth={w * 0.3} strokeLinecap="round" opacity="0.45" transform="translate(-0.5 -0.5)" />
    </g>
  );
}
