/* ================= 5. 木霊の大樹（歩く大樹） ================= */
function ZkGrass5Defs() {
  return (
    <defs>
      <linearGradient id="zkGrass5Bark" x1="0.1" y1="0" x2="0.9" y2="0.6"><stop offset="0" stopColor="#C49460" /><stop offset="0.45" stopColor="#6E4626" /><stop offset="1" stopColor="#22130A" /></linearGradient>
      <radialGradient id="zkGrass5Crown" cx="0.35" cy="0.3" r="0.8"><stop offset="0" stopColor="#D8BC6A" /><stop offset="0.5" stopColor="#7C6A2C" /><stop offset="1" stopColor="#2E2610" /></radialGradient>
      <radialGradient id="zkGrass5Hollow" cx="0.5" cy="0.5"><stop offset="0" stopColor="#FFE8A0" /><stop offset="0.4" stopColor="#E88A30" /><stop offset="1" stopColor="#2A0E04" /></radialGradient>
      <radialGradient id="zkGrass5Mote"><stop offset="0" stopColor="#FFF4C8" /><stop offset="0.4" stopColor="#FFC860" stopOpacity="0.8" /><stop offset="1" stopColor="#E08A3A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkGrass5Crown({ blobs }) {
  return (
    <g>
      {blobs.map(([x, y, r], i) => <circle key={i} cx={x} cy={y} r={r} fill="url(#zkGrass5Crown)" />)}
    </g>
  );
}
function ZkGrass5Motes({ pts }) {
  return pts.map(([x, y, r, d], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill="url(#zkGrass5Mote)" /></g></g>
  ));
}
