        <g className="zk-shine"><path d="M44 52 C50 50 56 52 62 50 M52 62 C58 60 64 62 70 60" fill="none" stroke="#FFC060" strokeWidth="0.8" strokeLinecap="round" opacity="0.8" /></g>
        {/* 背の茨 */}
