        {/* 首と頭：低く伸ばして噛みつく */}
        <path d="M40 46 C34 42 28 40 22 42 L22 54 C28 54 34 56 40 58 Z" fill="url(#zkGrass6Bark)" {...zkGrass6Edge} />
        {/* 上あご */}
        <path d="M30 38 C24 36 18 38 12 42 C8 44 8 46 10 47 L24 48 L30 50 Z" fill="url(#zkGrass6Bark)" {...zkGrass6Edge} />
