const ZK_T_grass = [
  [ZkGrass1S, ZkGrass1Q, ZkGrass1F],
  [ZkGrass2S, ZkGrass2Q, ZkGrass2F],
  [ZkGrass3S, ZkGrass3Q, ZkGrass3F],
  [ZkGrass4S, ZkGrass4Q, ZkGrass4F],
  [ZkGrass5S, ZkGrass5Q, ZkGrass5F],
  [ZkGrass6S, ZkGrass6Q, ZkGrass6F],
];
/* ---- /zk:grass ---- */
/* ---- zk:fire ---- */
// ZKT/fire.jsx — ほのお（系統 fire）：火鼠・サラマンダー・狐火（試作）・輪入道・炎獅子・溶岩獣
/* ---- 共有の小物 ---- */
// 炎の舌（根元が 0,0、上へ伸びる）。外側の g で位置と向きを決め、内側で揺らす
function ZkFire1Flame({ t, g, d = "0ms", o = 1 }) {
  return (
    <g transform={t}><g className="zk-flick" style={{ animationDelay: d }}>
      <path d="M-5 2 C-9 -6 -6 -14 -2 -18 C-2 -12 1 -10 2 -7 C3 -13 6 -19 4 -28 C12 -20 14 -8 7 2 Z" fill={`url(#${g})`} opacity={o} />
    </g></g>
  );
}
// 立ちのぼる火の粉
function ZkFire1Embers({ pts }) {
  return (
    <g>
      {pts.map(([x, y, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-fire-rise" style={{ animationDelay: `${d}ms` }}>
          <circle r="1.8" fill="#FF7A2A" opacity="0.55" /><circle r="0.8" fill="#FFF4C0" />
        </g></g>
      ))}
    </g>
  );
}
// 溶岩の割れ目（外の滲み＋芯）
function ZkFire2Crack({ d, w = 1, dl = "0ms" }) {
  return (
    <g className="zk-shine" style={{ animationDelay: dl }}>
      <path d={d} fill="none" stroke="#FF4A1A" strokeWidth={2.4 * w} opacity="0.45" strokeLinejoin="round" strokeLinecap="round" />
      <path d={d} fill="none" stroke="#FFC060" strokeWidth={0.9 * w} strokeLinejoin="round" strokeLinecap="round" />
    </g>
  );
}

/* ================= 1 火鼠 ================= */
function ZkFire1Defs() {
  return (
    <defs>
      <linearGradient id="zkFire1Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FF9A50" /><stop offset="0.5" stopColor="#D0402A" /><stop offset="1" stopColor="#5A1410" /></linearGradient>
      <linearGradient id="zkFire1Flame" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#C8321E" /><stop offset="0.5" stopColor="#FF8A3A" /><stop offset="1" stopColor="#FFF0A0" /></linearGradient>
      <linearGradient id="zkFire1Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFE4B8" /><stop offset="1" stopColor="#E8985A" /></linearGradient>
      <linearGradient id="zkFire1Tail" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#8A2A18" /><stop offset="1" stopColor="#FFB040" /></linearGradient>
    </defs>
  );
}
