/* ================= 4 輪入道 ================= */
function ZkFire4Defs() {
  return (
    <defs>
      <linearGradient id="zkFire4Face" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#F07A4A" /><stop offset="0.55" stopColor="#B82E1E" /><stop offset="1" stopColor="#5A1010" /></linearGradient>
      <linearGradient id="zkFire4Flame" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#C8321E" /><stop offset="0.5" stopColor="#FF8A3A" /><stop offset="1" stopColor="#FFF0A0" /></linearGradient>
      <linearGradient id="zkFire4Horn" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#FFF4D8" /><stop offset="0.6" stopColor="#C8A070" /><stop offset="1" stopColor="#4A2A18" /></linearGradient>
    </defs>
  );
}
// 回る車輪（中心 0,0）。⚠️ zk-fire-spin の内側に置く
function ZkFire4Wheel() {
  const a = [0, 45, 90, 135, 180, 225, 270, 315];
  return (
    <g>
      <circle r="31" fill="none" stroke="#3A2622" strokeWidth="1.8" />
      <circle r="28" fill="none" stroke="#9A5A2E" strokeWidth="6" />
      <circle r="25" fill="none" stroke="#4A2410" strokeWidth="0.7" opacity="0.7" />
      {a.map((d, i) => {
        const c = Math.cos(d * Math.PI / 180), s = Math.sin(d * Math.PI / 180);
        return <path key={i} d={`M${12 * c} ${12 * s} L${25 * c} ${25 * s}`} stroke={i % 2 ? "#7A4220" : "#9A5A2E"} strokeWidth="3.4" />;
      })}
      {a.map((d, i) => {
        const r = (d + 22.5) * Math.PI / 180;
        return <circle key={"r" + i} cx={28 * Math.cos(r)} cy={28 * Math.sin(r)} r="0.9" fill="#E8C46A" />;
      })}
    </g>
  );
}
// 静止した明暗（左上に光、右下に影）
function ZkFire4Shade() {
  return (
    <g>
      <path d="M-26.3 -9.6 A28 28 0 0 1 4.9 -27.6" fill="none" stroke="#FFD8A0" strokeWidth="1.4" opacity="0.6" />
      <path d="M26.3 9.6 A28 28 0 0 1 -9.6 26.3" fill="none" stroke="#1A0806" strokeWidth="5" opacity="0.45" />
    </g>
  );
}
