/* ================= 2. 角トカゲ竜（冠のある小竜） ================= */
function ZkDragon2Defs() {
  return (
    <defs>
      <linearGradient id="zkDragon2Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#E0784A" /><stop offset="0.5" stopColor="#8E2E1E" /><stop offset="1" stopColor="#2E0C0A" /></linearGradient>
      <radialGradient id="zkDragon2Frill" cx="0.5" cy="0.95" r="0.9"><stop offset="0" stopColor="#FFF0A0" /><stop offset="0.4" stopColor="#FFA040" /><stop offset="0.8" stopColor="#D8382A" /><stop offset="1" stopColor="#7A1A14" /></radialGradient>
      <linearGradient id="zkDragon2Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F8D8A8" /><stop offset="1" stopColor="#C8784A" /></linearGradient>
      <linearGradient id="zkDragon2Horn" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#B8802A" /><stop offset="1" stopColor="#FFF0C0" /></linearGradient>
      <radialGradient id="zkDragon2Spark"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFE07A" /><stop offset="1" stopColor="#FF6A3A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 襟巻き：原点＝首元、上へ扇状に開く */
function ZkDragon2Frill({ r = 20, a0 = 195, a1 = 345, n = 7 }) {
  const pts = [];
  const rib = [];
  for (let k = 0; k < n; k++) {
    const a = ((a0 + ((a1 - a0) * k) / (n - 1)) * Math.PI) / 180;
    const ox = (r * Math.cos(a)).toFixed(1), oy = (r * Math.sin(a)).toFixed(1);
    pts.push(`L${ox} ${oy}`);
    rib.push(`M0 0 L${(0.92 * r * Math.cos(a)).toFixed(1)} ${(0.92 * r * Math.sin(a)).toFixed(1)}`);
    if (k < n - 1) {
      const b = ((a0 + ((a1 - a0) * (k + 0.5)) / (n - 1)) * Math.PI) / 180;
      pts.push(`L${(0.74 * r * Math.cos(b)).toFixed(1)} ${(0.74 * r * Math.sin(b)).toFixed(1)}`);
    }
  }
  return (
    <g>
      <path d={`M0 0 ${pts.join(" ")} Z`} fill="url(#zkDragon2Frill)" stroke="#7A1A14" strokeWidth="0.5" />
      <path d={rib.join(" ")} fill="none" stroke="#8A2414" strokeWidth="0.7" opacity="0.65" />
    </g>
  );
}
function ZkDragon2Sparks({ pts }) {
  return pts.map(([x, y, d, s = 1], i) => (
    <g key={i} transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r="3.4" fill="url(#zkDragon2Spark)" /></g></g>
  ));
}
