function ZkDragon4Defs() {
  return (
    <defs>
      <linearGradient id="zkDragon4Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#C84058" /><stop offset="0.5" stopColor="#6A1830" /><stop offset="1" stopColor="#22060E" /></linearGradient>
      <linearGradient id="zkDragon4Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F4B878" /><stop offset="1" stopColor="#A8482A" /></linearGradient>
      <linearGradient id="zkDragon4Gold" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#B8802A" /><stop offset="1" stopColor="#FFF0C0" /></linearGradient>
      <linearGradient id="zkDragon4Fire" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#E8483A" /><stop offset="0.5" stopColor="#FF9A3A" /><stop offset="1" stopColor="#FFF0A0" stopOpacity="0.9" /></linearGradient>
      <radialGradient id="zkDragon4Ember"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFC86A" /><stop offset="1" stopColor="#FF5A2A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
