const ZK_T_dragon = [
  [ZkDragon1S, ZkDragon1Q, ZkDragon1F],
  [ZkDragon2S, ZkDragon2Q, ZkDragon2F],
  [ZkDragon3S, ZkDragon3Q, ZkDragon3F],
  [ZkDragon4S, ZkDragon4Q, ZkDragon4F],
  [ZkDragon5S, ZkDragon5Q, ZkDragon5F],
  [ZkDragon6S, ZkDragon6Q, ZkDragon6F],
];
/* ---- /zk:dragon ---- */
/* ---- zk:steel ---- */
// ZKT/steel.jsx — はがね（系統 fire）：ゼンマイ虫・刀の付喪神・空鎧・鋼蜘蛛・戦車獣・鉄竜
// 鉄の黒と真鍮に、炉の橙の光。
/* ---- 共有の小物 ---- */
// 暗い鉄の縁に入れる炉色の細い線
const ZkSteel1Rim = { stroke: "#FF8A3A", strokeWidth: 0.7, strokeOpacity: 0.62, strokeLinejoin: "round" };
// 歯車の輪郭（中心 0,0）
function ZkSteel1GearD(r, n) {
  const st = (Math.PI * 2) / n, ri = r * 0.76;
  let s = "";
  for (let i = 0; i < n; i++) {
    const a = i * st;
    [[ri, a - st * 0.3], [r, a - st * 0.17], [r, a + st * 0.17], [ri, a + st * 0.3]].forEach(([rr, aa], j) => {
      s += (i === 0 && j === 0 ? "M" : "L") + (rr * Math.cos(aa)).toFixed(2) + " " + (rr * Math.sin(aa)).toFixed(2) + " ";
    });
  }
  return s + "Z";
}
// 回る歯車。外側の g で位置、内側で回す
function ZkSteel1Gear({ x, y, r, n = 10, fill, rev, dur = "6s", sx = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${sx} 1)`}><g className={rev ? "zk-steel-spinr" : "zk-steel-spin"} style={{ animationDuration: dur }}>
      <path d={ZkSteel1GearD(r, n)} fill={fill} stroke="#4A2A0A" strokeWidth="0.4" />
      <circle r={r * 0.52} fill="none" stroke="#6A4214" strokeWidth="0.6" opacity="0.8" />
      <path d={`M${-r * 0.5} 0 L${r * 0.5} 0 M0 ${-r * 0.5} L0 ${r * 0.5}`} stroke="#6A4214" strokeWidth="0.8" />
      <circle r={r * 0.22} fill="#1A1008" /><circle r={r * 0.1} fill="#FFE0A0" />
    </g></g>
  );
}
// 立ちのぼる火の粉
function ZkSteel1Embers({ pts }) {
  return (
    <g>
      {pts.map(([x, y, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-steel-rise" style={{ animationDelay: `${d}ms` }}>
          <circle r="1.8" fill="#FF7A2A" opacity="0.5" /><circle r="0.75" fill="#FFF0C0" />
        </g></g>
      ))}
    </g>
  );
}
// 板の継ぎ目から漏れる炉の光
function ZkSteel1Seam({ d, w = 1, dl = "0ms" }) {
  return (
    <g className="zk-shine" style={{ animationDelay: dl }}>
      <path d={d} fill="none" stroke="#FF5A1A" strokeWidth={2.2 * w} opacity="0.45" strokeLinecap="round" strokeLinejoin="round" />
      <path d={d} fill="none" stroke="#FFC870" strokeWidth={0.8 * w} strokeLinecap="round" strokeLinejoin="round" />
    </g>
  );
}
// 炉色に光る目（丸）
function ZkSteel1Eye({ x, y, r = 2.4, ry, d = "0ms" }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r * 2} fill="url(#zkSteel1Hot)" opacity="0.7" />
      <g className="zk-blink" style={{ animationDelay: d }}>
        <ellipse cx={x} cy={y} rx={r} ry={ry || r} fill="#FFA030" />
        <ellipse cx={x - r * 0.25} cy={y - (ry || r) * 0.2} rx={r * 0.45} ry={(ry || r) * 0.45} fill="#FFF4C8" />
      </g>
    </g>
  );
}
// 真鍮の鋲
function ZkSteel1Rivets({ pts, r = 0.8 }) {
  return <g>{pts.map(([x, y], i) => <circle key={i} cx={x} cy={y} r={r} fill="#E8B860" stroke="#5A3410" strokeWidth="0.3" />)}</g>;
}
// 関節つきの脚（点列）。far で奥の脚
function ZkSteel1Leg({ pts, w = 2.6, far }) {
  const d = pts.map(([x, y], i) => (i ? "L" : "M") + x + " " + y).join(" ");
  return (
    <g>
      <path d={d} fill="none" stroke={far ? "#1A1B22" : "#0E0F14"} strokeWidth={w + 1} strokeLinecap="round" strokeLinejoin="round" />
      <path d={d} fill="none" stroke={far ? "#2C2E36" : "#747A88"} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
      {!far && <path d={d} fill="none" stroke="#C8D0DC" strokeWidth={w * 0.3} strokeLinecap="round" strokeLinejoin="round" opacity="0.45" transform="translate(-0.4 -0.5)" />}
      {pts.slice(1, -1).map(([x, y], i) => <circle key={i} cx={x} cy={y} r={w * 0.55} fill={far ? "#5A3A18" : "#E0A850"} />)}
    </g>
  );
}

/* ================= 1 ゼンマイ虫 ================= */
function ZkSteel1Defs() {
  return (
    <defs>
      <linearGradient id="zkSteel1Shell" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#9AA2B4" /><stop offset="0.42" stopColor="#3E4250" /><stop offset="1" stopColor="#101117" /></linearGradient>
      <linearGradient id="zkSteel1Brass" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFEAB0" /><stop offset="0.5" stopColor="#D89C3A" /><stop offset="1" stopColor="#6A3E12" /></linearGradient>
      <radialGradient id="zkSteel1Hot"><stop offset="0" stopColor="#FFF4C8" /><stop offset="0.35" stopColor="#FFB040" stopOpacity="0.8" /><stop offset="1" stopColor="#E8483A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkSteel1Key({ x, y, s = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      <path d="M-1.2 0 L1.2 0 L1.2 9 L-1.2 9 Z" fill="url(#zkSteel1Brass)" />
      <g className="zk-steel-wind">
        <path d="M0 0.4 C-3 -1 -9 0 -9.4 -4.6 C-9.6 -9 -3.6 -9.4 0 -5 C3.6 -9.4 9.6 -9 9.4 -4.6 C9 0 3 -1 0 0.4 Z" fill="url(#zkSteel1Brass)" stroke="#5A3410" strokeWidth="0.5" />
        <circle cx="-5.4" cy="-4.4" r="1.5" fill="#1A1008" /><circle cx="5.4" cy="-4.4" r="1.5" fill="#1A1008" />
      </g>
    </g>
  );
}
