/* ================= 4 鋼蜘蛛 ================= */
function ZkSteel4Defs() {
  return (
    <defs>
      <linearGradient id="zkSteel4Plate" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A0A8B8" /><stop offset="0.45" stopColor="#434856" /><stop offset="1" stopColor="#121318" /></linearGradient>
      <linearGradient id="zkSteel4Brass" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFEAB0" /><stop offset="0.5" stopColor="#D89C3A" /><stop offset="1" stopColor="#6A3E12" /></linearGradient>
      <radialGradient id="zkSteel1Hot"><stop offset="0" stopColor="#FFF4C8" /><stop offset="0.35" stopColor="#FFB040" stopOpacity="0.8" /><stop offset="1" stopColor="#E8483A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 蜘蛛の光学眼（赤橙）
function ZkSteel4Optic({ x, y, r, d = "0ms" }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r * 1.9} fill="url(#zkSteel1Hot)" opacity="0.65" />
      <circle cx={x} cy={y} r={r + 0.5} fill="#1A0A06" stroke="url(#zkSteel4Brass)" strokeWidth="0.5" />
      <g className="zk-blink" style={{ animationDelay: d }}>
        <circle cx={x} cy={y} r={r} fill="#FF6A2A" /><circle cx={x - r * 0.3} cy={y - r * 0.3} r={r * 0.4} fill="#FFE8B0" />
      </g>
    </g>
  );
}
