/* ================= 5 戦車獣 ================= */
function ZkSteel5Defs() {
  return (
    <defs>
      <linearGradient id="zkSteel5Hull" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#9AA2B2" /><stop offset="0.42" stopColor="#3E4250" /><stop offset="1" stopColor="#101116" /></linearGradient>
      <linearGradient id="zkSteel5Brass" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFEAB0" /><stop offset="0.5" stopColor="#D89C3A" /><stop offset="1" stopColor="#6A3E12" /></linearGradient>
      <linearGradient id="zkSteel5Tread" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#3A3C46" /><stop offset="1" stopColor="#0E0F14" /></linearGradient>
      <radialGradient id="zkSteel1Hot"><stop offset="0" stopColor="#FFF4C8" /><stop offset="0.35" stopColor="#FFB040" stopOpacity="0.8" /><stop offset="1" stopColor="#E8483A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 炉の心臓（格子の奥で燃える）
function ZkSteel5Heart({ x, y, w, h }) {
  return (
    <g>
      <rect x={x - w / 2} y={y - h / 2} width={w} height={h} rx={h * 0.3} fill="#1A0A06" stroke="url(#zkSteel5Brass)" strokeWidth="1.2" />
      <g className="zk-glow"><ellipse cx={x} cy={y} rx={w * 0.62} ry={h * 0.62} fill="url(#zkSteel1Hot)" /></g>
      {[-0.3, 0, 0.3].map((k, i) => <path key={i} d={`M${x + k * w} ${y - h / 2 + 0.6} L${x + k * w} ${y + h / 2 - 0.6}`} stroke="#2A1408" strokeWidth="1.2" />)}
    </g>
  );
}
// 履帯（横から）
function ZkSteel5Tread({ x1, x2, y1, y2, wheels }) {
  const r = (y2 - y1) / 2;
  const d = `M${x1 + r} ${y1} L${x2 - r} ${y1} A${r} ${r} 0 0 1 ${x2 - r} ${y2} L${x1 + r} ${y2} A${r} ${r} 0 0 1 ${x1 + r} ${y1} Z`;
  return (
    <g>
      <path d={d} fill="url(#zkSteel5Tread)" {...ZkSteel1Rim} />
      <path className="zk-steel-tread" d={d} fill="none" stroke="#6A707E" strokeWidth="1.6" strokeDasharray="1.6 1.6" />
      {wheels.map((wx, i) => <ZkSteel1Gear key={i} x={wx} y={(y1 + y2) / 2} r={r * 0.62} n={8} fill="url(#zkSteel5Brass)" dur="3s" rev />)}
    </g>
  );
}
