/* ---- zk:water ---- */
// ZKT/water.jsx
/* ================= 共通の小道具 ================= */
// しずく（落ちる）
function ZkWater0Drop({ x, y, d = 0, s = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-drip" style={{ animationDelay: `${d}ms` }}>
      <path d="M0 -2 C1.4 0 1.4 1.6 0 2 C-1.4 1.6 -1.4 0 0 -2 Z" fill="#9AD8FF" />
    </g></g>
  );
}
// 漂う泡・粒
function ZkWater0Bubble({ x, y, r = 1.6, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}>
      <circle r={r} fill="#DDF4FF" fillOpacity="0.18" stroke="#BFEAFF" strokeWidth="0.5" />
      <circle cx={-r * 0.35} cy={-r * 0.35} r={r * 0.28} fill="#FFFFFF" />
    </g></g>
  );
}
// 三次曲線に沿って先細りする形（触腕・尾・脚）
function ZkWater0Taper(p, w0, w1, n = 16) {
  const L = [], R = [], pts = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n, u = 1 - t;
    const x = u * u * u * p[0] + 3 * u * u * t * p[2] + 3 * u * t * t * p[4] + t * t * t * p[6];
    const y = u * u * u * p[1] + 3 * u * u * t * p[3] + 3 * u * t * t * p[5] + t * t * t * p[7];
    const dx = 3 * u * u * (p[2] - p[0]) + 6 * u * t * (p[4] - p[2]) + 3 * t * t * (p[6] - p[4]);
    const dy = 3 * u * u * (p[3] - p[1]) + 6 * u * t * (p[5] - p[3]) + 3 * t * t * (p[7] - p[5]);
    const l = Math.hypot(dx, dy) || 1, nx = -dy / l, ny = dx / l, w = (w0 + (w1 - w0) * t) / 2;
    L.push([x + nx * w, y + ny * w]); R.push([x - nx * w, y - ny * w]); pts.push([x, y, nx, ny, w]);
  }
  const f = (q) => q[0].toFixed(1) + " " + q[1].toFixed(1);
  const d = "M" + L.map(f).join(" L") + " L" + R.reverse().map(f).join(" L") + " Z";
  return { d, pts };
}
function ZkWater0Arm({ p, w0 = 7, w1 = 1, fill, side = 1, suck = true, stroke, sw = 0.6, cup = "#DDF4FF" }) {
  const { d, pts } = ZkWater0Taper(p, w0, w1);
  return (
    <g>
      <path d={d} fill={fill} stroke={stroke} strokeWidth={stroke ? sw : undefined} strokeOpacity="0.65" strokeLinejoin="round" />
      {suck && pts.filter((q, i) => i % 2 === 1 && i < pts.length - 2).map(([x, y, nx, ny, w], i) => (
        <circle key={i} cx={x - side * nx * w * 0.5} cy={y - side * ny * w * 0.5} r={Math.max(0.5, w * 0.36)} fill={cup} opacity="0.75" />
      ))}
    </g>
  );
}

/* ================= 1. 雫ガエル（b1） ================= */
function ZkWater1Defs() {
  return (
    <defs>
      <linearGradient id="zkWater1Skin" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#8AD4FF" /><stop offset="0.5" stopColor="#3A8AE8" /><stop offset="1" stopColor="#15357A" /></linearGradient>
      <linearGradient id="zkWater1Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F2FBFF" /><stop offset="1" stopColor="#8EC0E4" /></linearGradient>
      <radialGradient id="zkWater1Orb" cx="0.36" cy="0.32" r="0.72"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.3" stopColor="#CFF2FF" /><stop offset="0.75" stopColor="#4AA8F0" /><stop offset="1" stopColor="#1E5AC0" /></radialGradient>
    </defs>
  );
}
function ZkWater1Web({ x, y, a = 0, s = 1, c = "#23559C" }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${a}) scale(${s})`}>
      <path d="M0 -2.4 L-7 -4.6 L-5.2 -1.2 L-8 1 L-5.2 2 L-7 5.4 L0 2.6 Z" fill={c} />
      <circle cx="-7" cy="-4.6" r="1.1" fill="#9AD0FF" /><circle cx="-8" cy="1" r="1.1" fill="#9AD0FF" /><circle cx="-7" cy="5.4" r="1.1" fill="#9AD0FF" />
    </g>
  );
}
function ZkWater1Orb({ x, y, r = 8.5 }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r} fill="url(#zkWater1Orb)" />
      <path d={`M${x - r * 0.62} ${y + r * 0.42} Q${x} ${y + r * 0.86} ${x + r * 0.62} ${y + r * 0.42}`} fill="none" stroke="#DDF4FF" strokeWidth="0.7" opacity="0.7" />
      <g className="zk-shine"><ellipse cx={x - r * 0.32} cy={y - r * 0.38} rx={r * 0.26} ry={r * 0.18} fill="#FFFFFF" /></g>
    </g>
  );
}
function ZkWater1Eye({ x, y, rx = 3.8, ry = 4, px = -1.2 }) {
  return (
    <g>
      <ellipse className="zk-blink" cx={x} cy={y} rx={rx} ry={ry} fill="#BFF0FF" />
      <ellipse cx={x + px} cy={y + 0.4} rx={rx * 0.52} ry={ry * 0.3} fill="#0A1E48" />
      <circle cx={x + px - rx * 0.3} cy={y - ry * 0.3} r={rx * 0.16} fill="#FFFFFF" />
    </g>
  );
}
