/* ================= 5. 海坊主（b3） ================= */
function ZkWater5Defs() {
  return (
    <defs>
      <linearGradient id="zkWater5Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#3E62A8" /><stop offset="0.45" stopColor="#16285E" /><stop offset="1" stopColor="#060C28" /></linearGradient>
      <radialGradient id="zkWater5Eye" r="0.5"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.45" stopColor="#BFF4FF" /><stop offset="0.75" stopColor="#4AB0F8" stopOpacity="0.6" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
      <linearGradient id="zkWater5Foam" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="1" stopColor="#7AC0F0" stopOpacity="0.5" /></linearGradient>
      <linearGradient id="zkWater5Fall" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#DDF4FF" stopOpacity="0.9" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></linearGradient>
    </defs>
  );
}
function ZkWater5Eye({ x, y, r = 5, sq = 1 }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r * 1.9} fill="url(#zkWater5Eye)" opacity="0.55" />
      <ellipse className="zk-blink" cx={x} cy={y} rx={r} ry={r * 0.8 * sq} fill="url(#zkWater5Eye)" />
      <ellipse cx={x} cy={y} rx={r * 0.42} ry={r * 0.34 * sq} fill="#FFFFFF" />
    </g>
  );
}
function ZkWater5Foam({ x, y, w = 14, s = 1 }) {
  return (
    <path d={`M${x} ${y} q${w * 0.25} ${-5 * s} ${w * 0.5} ${-2 * s} q${w * 0.2} ${-4 * s} ${w * 0.5} ${2 * s} Z`} fill="url(#zkWater5Foam)" />
  );
}
const ZK_WATER5_RIM = { stroke: "#6AB8FF", strokeWidth: 0.8, strokeOpacity: 0.7 };
function ZkWater5S() {
  return (
    <g>
      <ZkWater5Defs />
      {/* 漂う粒 */}
      <ZkWater0Bubble x={86} y={24} r={1.4} />
      <ZkWater0Bubble x={14} y={30} r={1.2} d={-1300} />
      <g className="zk-breathe"><g transform="rotate(-6 56 92)">
        {/* 巨体：波のように前へのしかかる */}
        <path d="M28 90 C22 78 20 60 26 44 C32 28 42 17 56 16 C70 15 80 26 82 40 C85 56 84 70 90 82 C92 88 90 92 84 92 Z" fill="url(#zkWater5Body)" {...ZK_WATER5_RIM} />
        {/* 波の腕：前へ巻き込む */}
        <path d="M32 58 C24 50 14 50 9 58 C6 64 9 72 16 72 C12 68 13 62 18 61 C22 60 26 64 28 70 Z" fill="url(#zkWater5Body)" {...ZK_WATER5_RIM} />
        <path d="M10 60 C12 54 20 52 26 56" fill="none" stroke="#DDF4FF" strokeWidth="1.2" opacity="0.7" strokeLinecap="round" />
        {/* 流れ落ちる水 */}
        <g className="zk-shine">
          <path d="M44 22 C38 34 36 48 38 64 M62 20 C64 36 66 56 70 80 M74 34 C76 48 78 64 84 84" fill="none" stroke="url(#zkWater5Fall)" strokeWidth="1.2" strokeLinecap="round" />
        </g>
        <path d="M40 22 C48 17 60 17 68 22" fill="none" stroke="#9AD0FF" strokeWidth="1.1" opacity="0.6" strokeLinecap="round" />
        {/* 口（暗い裂け目） */}
        <path d="M24 50 Q31 55 38 51 Q31 53 24 50 Z" fill="#02061A" />
        {/* 目 */}
        <ZkWater5Eye x={34} y={36} r={5} />
        <ZkWater5Eye x={48} y={33} r={2.6} sq={0.7} />
        {/* 足元の波頭 */}
        <ZkWater5Foam x={24} y={90} w={16} />
        <ZkWater5Foam x={46} y={92} w={18} s={1.2} />
        <ZkWater5Foam x={70} y={92} w={16} />
      </g></g>
      <ZkWater0Drop x={12} y={72} d={-300} />
      <ZkWater0Drop x={30} y={74} d={-1400} s={0.8} />
      <ZkWater0Drop x={86} y={80} d={-2000} />
    </g>
  );
}
