/* ================= 3. 雪の番兵（b2） ================= */
function ZkIce3Defs() {
  return (
    <defs>
      <linearGradient id="zkIce3Snow" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#B8D2EA" /><stop offset="1" stopColor="#3E5E8C" /></linearGradient>
      <linearGradient id="zkIce3Ice" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F4FCFF" /><stop offset="0.45" stopColor="#7ACAFF" /><stop offset="1" stopColor="#1E5AA8" /></linearGradient>
      <linearGradient id="zkIce3Helm" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#DDF4FF" /><stop offset="0.5" stopColor="#4A8AD0" /><stop offset="1" stopColor="#14305C" /></linearGradient>
      <linearGradient id="zkIce3Shaft" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#DDF4FF" /><stop offset="1" stopColor="#3A7AC8" /></linearGradient>
      <radialGradient id="zkIce3Glow"><stop offset="0" stopColor="#BFF4FF" stopOpacity="0.9" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkIce3Spear({ x, y, a, len = 80 }) {
  // (x,y)＝石突き、a＝向き（0で左へ水平）
  return (
    <g transform={`translate(${x} ${y}) rotate(${a})`}>
      <path d={`M0 -1.3 L${-len} -1.1 L${-len} 1.1 L0 1.3 Z`} fill="url(#zkIce3Shaft)" />
      <path d={`M${-len + 2} -2.6 L${-len - 18} 0 L${-len + 2} 2.6 L${-len - 2} 0 Z`} fill="url(#zkIce3Ice)" />
      <g className="zk-shine"><path d={`M${-len - 16} 0 L${-len} -1.4`} stroke="#FFFFFF" strokeWidth="0.9" /></g>
      <path d={`M${-len + 1} -2 L${-len + 1} 2 M${-len + 4} -1.8 L${-len + 4} 1.8`} stroke="#E8C46A" strokeWidth="1.3" />
      <path d="M-4 -1.8 L-4 1.8" stroke="#E8C46A" strokeWidth="1.3" />
    </g>
  );
}
