/* ================= 4. ペンギン騎士（b2） ================= */
function ZkIce4Defs() {
  return (
    <defs>
      <linearGradient id="zkIce4Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#4A6A9E" /><stop offset="0.5" stopColor="#1A2C54" /><stop offset="1" stopColor="#0A1024" /></linearGradient>
      <linearGradient id="zkIce4Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="1" stopColor="#B8D4EC" /></linearGradient>
      <linearGradient id="zkIce4Armor" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F4FCFF" /><stop offset="0.45" stopColor="#8AD4FF" /><stop offset="1" stopColor="#2A62B8" /></linearGradient>
      <linearGradient id="zkIce4Beak" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFE08A" /><stop offset="1" stopColor="#C8802A" /></linearGradient>
      <linearGradient id="zkIce4Cape" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#3A7AD0" /><stop offset="1" stopColor="#12285A" /></linearGradient>
    </defs>
  );
}
function ZkIce4Blade({ x, y, a, l = 22 }) {
  // (x,y)＝柄頭、a＝向き（0で上）
  return (
    <g transform={`translate(${x} ${y}) rotate(${a})`}>
      <path d="M0 0 L0 -5" stroke="#6A4A2A" strokeWidth="2" strokeLinecap="round" />
      <path d="M-4.4 -5 L4.4 -5" stroke="#E8C46A" strokeWidth="2" strokeLinecap="round" />
      <path d={`M-2.4 -6 L-2.2 ${-l + 4} L0 ${-l} L2.2 ${-l + 4} L2.4 -6 Z`} fill="url(#zkIce4Armor)" />
      <path d={`M0 -6 L0 ${-l}  L2.2 ${-l + 4} L2.4 -6 Z`} fill="#1E4A90" opacity="0.3" />
      <g className="zk-shine"><path d={`M-1 -8 L-1 ${-l + 4}`} stroke="#FFFFFF" strokeWidth="0.8" /></g>
    </g>
  );
}
