/* ================= 5. 雪女（b3） ================= */
function ZkIce5Defs() {
  return (
    <defs>
      <linearGradient id="zkIce5Robe" x1="0.1" y1="0" x2="0.4" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.45" stopColor="#CDE6F8" /><stop offset="0.8" stopColor="#7AAEE0" stopOpacity="0.8" /><stop offset="1" stopColor="#5A9AE0" stopOpacity="0" /></linearGradient>
      <linearGradient id="zkIce5Sleeve" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.6" stopColor="#BCD8F0" /><stop offset="1" stopColor="#6A9ACE" /></linearGradient>
      <linearGradient id="zkIce5Hair" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#3E5078" /><stop offset="0.5" stopColor="#141C38" /><stop offset="1" stopColor="#080C1C" /></linearGradient>
      <linearGradient id="zkIce5Skin" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="1" stopColor="#B4CCE6" /></linearGradient>
    </defs>
  );
}
const ZK_ICE5_RIM = { stroke: "#8AD4FF", strokeWidth: 0.7, strokeOpacity: 0.65 };
// 裾のほどけ（吹雪の筋）
function ZkIce5Wisps({ list }) {
  return (
    <g>{list.map(([d, delay], i) => (
      <g key={i} className="zk-ice-drift" style={{ animationDelay: `${delay}ms` }}><path d={d} fill="none" stroke="#DDF4FF" strokeWidth="1" strokeLinecap="round" opacity="0.7" /></g>
    ))}</g>
  );
}
