        {/* 紫の斑点（少しだけ） */}
        <ZkPoison1Spots g="zkPoison1Spot" pts={[[52, 52, 3.2], [62, 60, 2.2], [44, 66, 1.8], [68, 70, 1.6], [56, 46, 1.4]]} />
        {/* 口（開けて舌を撃つ） */}
