/* ===================== 6 ヒュドラ ===================== */
function ZkPoison6Defs() {
  return (
    <defs>
      <linearGradient id="zkPoison6Scale" x1="0.2" y1="0" x2="0.8" y2="1">
        <stop offset="0" stopColor="#62BCA8" /><stop offset="0.45" stopColor="#185A62" /><stop offset="1" stopColor="#061C24" />
      </linearGradient>
      <linearGradient id="zkPoison6Horn" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="1" stopColor="#A8801A" /></linearGradient>
      <radialGradient id="zkPoison6Spot" cx="0.35" cy="0.3"><stop offset="0" stopColor="#D8B8FF" /><stop offset="0.6" stopColor="#8A4ACC" /><stop offset="1" stopColor="#3A1A6A" /></radialGradient>
      <radialGradient id="zkPoison6Aura"><stop offset="0" stopColor="#BFFFF0" stopOpacity="0.8" /><stop offset="1" stopColor="#3AC8B0" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 首（太い線を三重に：縁の光・地・艶） */
function ZkPoison6Neck({ d, w = 8 }) {
  return (
    <g>
      <path d={d} fill="none" stroke="#6ADCD0" strokeOpacity="0.6" strokeWidth={w + 1.2} strokeLinecap="round" />
      <path d={d} fill="none" stroke="#1A5C64" strokeWidth={w} strokeLinecap="round" />
      <path d={d} fill="none" stroke="#5AB8A8" strokeWidth={w * 0.3} strokeLinecap="round" opacity="0.55" transform="translate(-1 -1.2)" />
    </g>
  );
}
/* 横顔の頭（左を向く。原点＝首のつけ根側） */
function ZkPoison6Head({ x, y, a = 0, s = 1, far, q, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${a}) scale(${s})`}>
      <path d="M3 -5 L11 -12 L7 -3 Z" fill="url(#zkPoison6Horn)" />
      <path d="M6 -2 C4 -8 -4 -10 -10 -8 C-16 -6 -20 -4 -22 -1 L-8 1 C-3 2 2 3 6 4 Z" fill={far ? "#134850" : "url(#zkPoison6Scale)"} stroke="#6ADCD0" strokeWidth="0.6" strokeOpacity="0.65" />
      <path d="M-22 -0.6 L-6 1.4 L-18 8.6 Z" fill="#3A0A2A" />
      <path d="M5 4 C-2 4 -8 6 -18 9 C-12 4 -9 2 -6 1.4 Z" fill="#0E3038" stroke="#6ADCD0" strokeWidth="0.5" strokeOpacity="0.5" />
      <path d="M-19.6 -0.4 L-18.6 3.6 L-17.4 -0.2 Z M-14 0.2 L-13.2 3 L-12.2 0.4 Z" fill="#F0FFF8" />
      <path className="zk-blink" d="M-11 -5.2 Q-8 -7.4 -5 -5.4 Q-8 -4 -11 -5.2 Z" fill="#BFF4FF" />
      {q ? <path className="zk-blink" d="M-6 -8.2 Q-4.4 -9.2 -2.8 -8.2 Q-4.4 -7.4 -6 -8.2 Z" fill="#BFF4FF" /> : null}
      <path d="M-12 -6.6 L-4 -7.4" stroke="#06202E" strokeWidth="0.8" />
      <ZkPoison1Drop x={-17} y={10} d={d} s={0.8} />
    </g>
  );
}
