/* ======================= 2. 子梟（大きな目の小梟） ======================= */
function ZkFly2Defs() {
  return (
    <defs>
      <linearGradient id="zkFly2Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#C8B690" /><stop offset="0.55" stopColor="#7A6848" /><stop offset="1" stopColor="#2E2618" /></linearGradient>
      <linearGradient id="zkFly2Face" x1="0.2" y1="0" x2="0.7" y2="1"><stop offset="0" stopColor="#FFF6E2" /><stop offset="1" stopColor="#BCA884" /></linearGradient>
      <linearGradient id="zkFly2Wing" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#A89070" /><stop offset="0.6" stopColor="#4E4030" /><stop offset="1" stopColor="#1E180E" /></linearGradient>
      <radialGradient id="zkFly2Iris" cx="0.4" cy="0.4" r="0.6"><stop offset="0" stopColor="#F0FFF4" /><stop offset="0.45" stopColor="#6AE088" /><stop offset="1" stopColor="#1A6A34" /></radialGradient>
      <linearGradient id="zkFly2Beak" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFE08A" /><stop offset="1" stopColor="#A8761A" /></linearGradient>
    </defs>
  );
}
function ZkFly2Wing({ o = 1 }) {
  return (
    <g opacity={o}>
      <path d="M0 0 C2 -12 12 -24 28 -28 C26 -22 28 -18 24 -14 C28 -11 26 -6 20 -5 C22 -1 18 2 12 2 C8 4 3 3 0 0 Z" fill="url(#zkFly2Wing)" stroke="#5AC874" strokeWidth="0.6" strokeOpacity="0.6" />
      <path d="M6 -6 L9 -8 M12 -10 L15 -12 M18 -15 L21 -17 M8 -1 L11 -3 M14 -5 L17 -7" stroke="#F0E6CC" strokeWidth="1" opacity="0.7" strokeLinecap="round" />
    </g>
  );
}
/* 大きな目（r：半径、sx：横つぶれ） */
function ZkFly2Eye({ x, y, r, sx = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${sx} 1)`}>
      <circle r={r + 1.2} fill="#1A140C" />
      <g className="zk-blink">
        <circle r={r} fill="url(#zkFly2Iris)" />
        <circle r={r * 0.42} fill="#06140A" />
        <circle cx={-r * 0.35} cy={-r * 0.35} r={r * 0.2} fill="#FFFFFF" />
      </g>
    </g>
  );
}
