/* ======================= 2 ケサランパサラン ======================= */
function ZkFairy2Path(rx, ry, n, k, ph = 0) {
  let d = "";
  for (let i = 0; i <= n; i++) {
    const t = (i + ph) / n * 2 * Math.PI, x = Math.cos(t) * rx, y = Math.sin(t) * ry;
    if (i === 0) d += `M${x.toFixed(1)} ${y.toFixed(1)}`;
    else { const m = (i - 0.5 + ph) / n * 2 * Math.PI; d += ` Q${(Math.cos(m) * rx * k).toFixed(1)} ${(Math.sin(m) * ry * k).toFixed(1)} ${x.toFixed(1)} ${y.toFixed(1)}`; }
  }
  return d + "Z";
}
function ZkFairy2Defs() {
  return (
    <defs>
      <radialGradient id="zkFairy2Fluff" cx="0.38" cy="0.32" r="0.72"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#E6F8EE" /><stop offset="1" stopColor="#6FA894" /></radialGradient>
      <radialGradient id="zkFairy2Core" cx="0.4" cy="0.38"><stop offset="0" stopColor="#FFFFFF" /><stop offset="1" stopColor="#FFFFFF" stopOpacity="0" /></radialGradient>
      <linearGradient id="zkFairy2Wisp" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#FFFFFF" stopOpacity="0.95" /><stop offset="0.55" stopColor="#BFF4D4" stopOpacity="0.6" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></linearGradient>
      <linearGradient id="zkFairy2WispL" x1="1" y1="0" x2="0" y2="0"><stop offset="0" stopColor="#FFFFFF" stopOpacity="0.95" /><stop offset="0.55" stopColor="#BFF4D4" stopOpacity="0.6" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></linearGradient>
      <radialGradient id="zkFairy2Glow"><stop offset="0" stopColor="#CFFFE0" stopOpacity="0.9" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkFairy2Ball({ rx, ry, n = 16, k = 1.14 }) {
  const hs = [];
  for (let a = 8; a < 360; a += 22) hs.push(a);
  return (
    <g>
      <path d={ZkFairy2Path(rx * 1.05, ry * 1.05, n, k * 1.02, 0.5)} fill="#A8DCC4" opacity="0.4" />
      <path d={ZkFairy2Path(rx, ry, n, k)} fill="url(#zkFairy2Fluff)" />
      {hs.map((a) => {
        const c = Math.cos(a * Math.PI / 180), s = Math.sin(a * Math.PI / 180);
        return <path key={a} d={`M${(c * rx * 0.72).toFixed(1)} ${(s * ry * 0.72).toFixed(1)} Q${(c * rx * 1.02 - s * 3).toFixed(1)} ${(s * ry * 1.02 + c * 3).toFixed(1)} ${(c * rx * 1.24).toFixed(1)} ${(s * ry * 1.24).toFixed(1)}`} fill="none" stroke="#FFFFFF" strokeWidth="0.5" opacity="0.65" strokeLinecap="round" />;
      })}
      <g transform={`translate(${(-rx * 0.2).toFixed(1)} ${(-ry * 0.24).toFixed(1)})`}><path d={ZkFairy2Path(rx * 0.6, ry * 0.55, 11, 1.18)} fill="url(#zkFairy2Core)" opacity="0.85" /></g>
    </g>
  );
}
/* 目：小さく明るい翡翠 */
function ZkFairy2Eye({ x, y, s = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}>
      <circle r="4.4" fill="url(#zkFairy2Glow)" />
      <g className="zk-blink"><ellipse rx="2" ry="2.5" fill="#1A5A36" /><ellipse cx="-0.2" cy="0.3" rx="1.4" ry="1.8" fill="#4ADC84" /><circle cx="-0.7" cy="-0.9" r="0.6" fill="#FFFFFF" /></g>
    </g>
  );
}
