/* ======================= 4 月うさぎ ======================= */
function ZkFairy4Defs() {
  return (
    <defs>
      <linearGradient id="zkFairy4Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#DCEFE6" /><stop offset="1" stopColor="#7FA898" /></linearGradient>
      <linearGradient id="zkFairy4FurD" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D4E8DE" /><stop offset="1" stopColor="#5E8474" /></linearGradient>
      <linearGradient id="zkFairy4Ear" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F0FFF4" /><stop offset="1" stopColor="#8ED4AC" /></linearGradient>
      <linearGradient id="zkFairy4Wood" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#E0B478" /><stop offset="0.5" stopColor="#8A5A2A" /><stop offset="1" stopColor="#3E2410" /></linearGradient>
      <linearGradient id="zkFairy4Sash" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#7AD898" /><stop offset="1" stopColor="#1E5A34" /></linearGradient>
      <radialGradient id="zkFairy4Glow"><stop offset="0" stopColor="#FFF6D0" stopOpacity="0.8" /><stop offset="1" stopColor="#E8C46A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 杵（手元 0,0 から -x へ柄、先に頭） */
function ZkFairy4Kine({ len = 26 }) {
  return (
    <g>
      <rect x={-len} y="-1.5" width={len + 3} height="3" rx="1.4" fill="url(#zkFairy4Wood)" />
      <rect x={-len - 11} y="-10.5" width="11" height="21" rx="3.4" fill="url(#zkFairy4Wood)" />
      <path d={`M${-len - 9} -8 L${-len - 9} 8`} stroke="#FFE0A8" strokeWidth="1" opacity="0.55" strokeLinecap="round" />
      <rect x={-len - 11} y="-7.4" width="11" height="1.6" fill="#E8C46A" /><rect x={-len - 11} y="5.8" width="11" height="1.6" fill="#E8C46A" />
    </g>
  );
}
/* 帯の三日月飾り（金） */
function ZkFairy4Moon({ x, y }) {
  return (
    <g transform={`translate(${x} ${y})`}>
      <g className="zk-shine"><circle r="5" fill="url(#zkFairy4Glow)" /></g>
      <path d="M-1 -3.4 C-4 -2 -4 2 -1 3.4 C-2.6 1.6 -2.6 -1.6 -1 -3.4 Z" fill="#FFE08A" stroke="#E8C46A" strokeWidth="0.5" />
    </g>
  );
}
