/* ======================= 6 水晶角の一角獣 ======================= */
function ZkFairy6Defs() {
  return (
    <defs>
      <linearGradient id="zkFairy6Coat" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#DDF0E6" /><stop offset="1" stopColor="#7EAA98" /></linearGradient>
      <linearGradient id="zkFairy6CoatD" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#C4DCD0" /><stop offset="1" stopColor="#5A8070" /></linearGradient>
      <linearGradient id="zkFairy6Mane" x1="0" y1="0" x2="1" y2="0.4"><stop offset="0" stopColor="#FFFFFF" stopOpacity="0.95" /><stop offset="0.5" stopColor="#B4F4CC" stopOpacity="0.8" /><stop offset="1" stopColor="#4AB860" stopOpacity="0.1" /></linearGradient>
      <linearGradient id="zkFairy6Horn" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#B8FFD8" /><stop offset="1" stopColor="#2E8A60" /></linearGradient>
      <linearGradient id="zkFairy6Hoof" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFE08A" /><stop offset="1" stopColor="#A8761A" /></linearGradient>
      <radialGradient id="zkFairy6Glint"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#CFFFE0" stopOpacity="0.8" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 水晶の角（根元 0,0 → 上へ、長さ h） */
function ZkFairy6Horn({ h = 18 }) {
  return (
    <g>
      <path d={`M-2.6 0 L0 ${-h} L2.6 0 Z`} fill="url(#zkFairy6Horn)" stroke="#8AF0B8" strokeWidth="0.4" />
      <path d={`M0 0 L0 ${-h} M-2 ${-h * 0.25} L1.6 ${-h * 0.4} M-1.4 ${-h * 0.55} L1.1 ${-h * 0.68}`} stroke="#FFFFFF" strokeWidth="0.45" opacity="0.8" />
      <g transform={`translate(0 ${-h})`}><g className="zk-shine"><circle r="4.4" fill="url(#zkFairy6Glint)" /></g></g>
    </g>
  );
}
