/* ================= 2. 拳鼠（カンガルーの拳闘士） ================= */
function ZkFight2Defs() {
  return (
    <defs>
      <linearGradient id="zkFight2Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#E8B478" /><stop offset="0.5" stopColor="#A8663A" /><stop offset="1" stopColor="#40200E" /></linearGradient>
      <linearGradient id="zkFight2Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFF2DC" /><stop offset="1" stopColor="#E0B488" /></linearGradient>
      <radialGradient id="zkFight2Glove" cx="0.35" cy="0.3"><stop offset="0" stopColor="#FFFBD8" /><stop offset="0.45" stopColor="#F0C830" /><stop offset="1" stopColor="#8A5E0C" /></radialGradient>
    </defs>
  );
}
function ZkFight2Glove({ x, y, s = 1, r = 0, cls = "zk-fight-jab", delay = "0ms" }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}><g className={cls} style={{ animationDelay: delay }}>
      <ellipse cx="0" cy="0" rx="6.4" ry="5.6" fill="url(#zkFight2Glove)" />
      <path d="M-3 -4.6 C-1 -3 -1 1 -3 3" fill="none" stroke="#8A5E0C" strokeWidth="0.6" opacity="0.7" />
      <rect x="4" y="-4" width="3.6" height="8" rx="1.3" fill="#FFF4E0" />
      <path d="M5.8 -3 L5.8 3" stroke="#C8A040" strokeWidth="0.5" />
      <ellipse cx="-2.2" cy="-2.4" rx="2" ry="1.3" fill="#FFFFFF" opacity="0.55" />
    </g></g>
  );
}
