        {[[40, 72, 30, 90], [50, 74, 46, 92], [62, 74, 66, 92], [72, 70, 77, 87]].map(([x1, y1, x2, y2], i) => (
          <path key={i} d={`M${x1} ${y1} Q${(x1 + x2) / 2 + (x2 > x1 ? 4 : -4)} ${y1 - 2} ${x2} ${y2}`} fill="none" stroke="url(#zkFight4Leg)" strokeWidth="3.4" strokeLinecap="round" />
        ))}
        {/* 甲羅：横から見た厚い丸み */}
