function ZkFight6Motes({ pts }) {
  return pts.map(([x, y, d, r], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r || 3.4} fill="url(#zkFight6Mote)" /></g></g>
  ));
}
