// ZKT/electric.jsx — でんき（系統 light）
/* ================= 1. 雷鼬（雷獣の子） ================= */
function ZkElectric1Defs() {
  return (
    <defs>
      <linearGradient id="zkElectric1Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A4AAE0" /><stop offset="0.5" stopColor="#555A96" /><stop offset="1" stopColor="#1E2048" /></linearGradient>
      <linearGradient id="zkElectric1Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFFBEA" /><stop offset="1" stopColor="#D8C890" /></linearGradient>
      <linearGradient id="zkElectric1Tail" x1="0" y1="1" x2="0.5" y2="0"><stop offset="0" stopColor="#23264E" /><stop offset="0.45" stopColor="#6A70B8" /><stop offset="0.72" stopColor="#F0C830" /><stop offset="1" stopColor="#FFFBD8" /></linearGradient>
      <radialGradient id="zkElectric1Spark"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFF0A0" /><stop offset="1" stopColor="#F0C830" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
