/* ================= 3. 雷鰻（電気ウナギ） ================= */
function ZkElectric3Defs() {
  return (
    <defs>
      <linearGradient id="zkElectric3Skin" x1="0.1" y1="0" x2="0.6" y2="1"><stop offset="0" stopColor="#7A9CB8" /><stop offset="0.45" stopColor="#34506E" /><stop offset="1" stopColor="#101C30" /></linearGradient>
      <linearGradient id="zkElectric3Head" x1="0.2" y1="0" x2="0.7" y2="1"><stop offset="0" stopColor="#8AAAC4" /><stop offset="0.5" stopColor="#3A5676" /><stop offset="1" stopColor="#12203A" /></linearGradient>
      <linearGradient id="zkElectric3Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F4E8B8" /><stop offset="1" stopColor="#B89A50" /></linearGradient>
      <radialGradient id="zkElectric3Spark"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFF0A0" /><stop offset="1" stopColor="#F0C830" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 胴：同じ道筋を 鰭の光 → 胴 → 腹の筋 → 走る稲妻 の順に重ねる */
function ZkElectric3Body({ d, tail, w = 10 }) {
  return (
    <g>
      <path d={d} fill="none" stroke="#F0C830" strokeOpacity="0.28" strokeWidth={w + 5} strokeLinecap="round" />
      <path d={tail} fill="none" stroke="#F0C830" strokeOpacity="0.28" strokeWidth={w - 1} strokeLinecap="round" />
      <path d={tail} fill="none" stroke="url(#zkElectric3Skin)" strokeWidth={w * 0.45} strokeLinecap="round" />
      <path d={d} fill="none" stroke="#0E1828" strokeWidth={w + 1.2} strokeLinecap="round" />
      <path d={d} fill="none" stroke="url(#zkElectric3Skin)" strokeWidth={w} strokeLinecap="round" />
      <path d={d} fill="none" stroke="#9ABAD4" strokeWidth={w * 0.22} strokeLinecap="round" opacity="0.45" transform="translate(-0.8 -2)" />
      <g className="zk-shine">
        <path d={d} fill="none" stroke="#FFF3A0" strokeWidth="1" strokeDasharray="5 2.4 1.6 2.4" strokeLinecap="round" />
      </g>
    </g>
  );
}
