/* ================= 5. 雷獣（雷を纏う狼獣） ================= */
function ZkElectric5Defs() {
  return (
    <defs>
      <linearGradient id="zkElectric5Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#9AA2D8" /><stop offset="0.45" stopColor="#3C4280" /><stop offset="1" stopColor="#12132E" /></linearGradient>
      {/* 胴の後ろ半分が稲妻に溶ける */}
      <linearGradient id="zkElectric5Fade" x1="0" y1="0" x2="1" y2="0.2"><stop offset="0" stopColor="#4A5090" /><stop offset="0.45" stopColor="#2A2E60" /><stop offset="0.75" stopColor="#6A68B0" stopOpacity="0.6" /><stop offset="1" stopColor="#FFF3A0" stopOpacity="0" /></linearGradient>
      <linearGradient id="zkElectric5Bolt" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#FFE870" /><stop offset="1" stopColor="#E0A820" stopOpacity="0.7" /></linearGradient>
      <linearGradient id="zkElectric5Mane" x1="0" y1="1" x2="0.3" y2="0"><stop offset="0" stopColor="#2A2E60" /><stop offset="0.5" stopColor="#C8A840" /><stop offset="1" stopColor="#FFFBE0" /></linearGradient>
      <linearGradient id="zkElectric5Ruff" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#1E2046" /><stop offset="0.6" stopColor="#4A5090" /><stop offset="1" stopColor="#8A92CC" /></linearGradient>
      <radialGradient id="zkElectric5Spark"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFF0A0" /><stop offset="1" stopColor="#F0C830" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkElectric5Bolt({ d, w = 1 }) {
  return (
    <g>
      <path d={d} fill="none" stroke="#F0C830" strokeWidth={3.6 * w} opacity="0.3" strokeLinejoin="round" strokeLinecap="round" />
      <path d={d} fill="none" stroke="#FFFBE0" strokeWidth={1.1 * w} strokeLinejoin="round" strokeLinecap="round" />
    </g>
  );
}
function ZkElectric5Sparks({ pts }) {
  return pts.map(([x, y, d, r = 3.4], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill="url(#zkElectric5Spark)" /></g></g>
  ));
}
