/* ================= 6. 雷虎（雷の虎） ================= */
function ZkElectric6Defs() {
  return (
    <defs>
      <linearGradient id="zkElectric6Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFBF0" /><stop offset="0.45" stopColor="#C4BCD4" /><stop offset="1" stopColor="#4A4470" /></linearGradient>
      <linearGradient id="zkElectric6Shade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#8A84A8" /><stop offset="1" stopColor="#2E2A4A" /></linearGradient>
      <linearGradient id="zkElectric6White" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="1" stopColor="#D4D0E4" /></linearGradient>
      <radialGradient id="zkElectric6Spark"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFF0A0" /><stop offset="1" stopColor="#F0C830" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 縞：暗い筋の芯に金の電熱線 */
function ZkElectric6Stripes({ d, w = 2.4, delay = "0ms" }) {
  return (
    <g>
      <path d={d} fill="none" stroke="#1C1830" strokeWidth={w} strokeLinecap="round" />
      <g className="zk-shine" style={{ animationDelay: delay }}>
        <path d={d} fill="none" stroke="#FFE36A" strokeWidth={w * 0.34} strokeLinecap="round" />
      </g>
    </g>
  );
}
function ZkElectric6Sparks({ pts }) {
  return pts.map(([x, y, d, r = 3.4], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill="url(#zkElectric6Spark)" /></g></g>
  ));
}
