      <linearGradient id="zkNormal2Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.55" stopColor="#E8DCC8" /><stop offset="1" stopColor="#8A7C6A" /></linearGradient>
