function ZkNormal3Mane({ pts, lean = 4 }) {
  return (
    <g>
      {pts.map(([x, y, h], i) => (
        <path key={i} d={`M${x - 2} ${y + 2} Q${x + lean * 0.3} ${y - h * 0.6} ${x + lean} ${y - h} Q${x + lean * 0.4} ${y - h * 0.4} ${x + 2.4} ${y + 2} Z`} fill="#2A180C" stroke="#F0C830" strokeWidth="0.4" strokeOpacity="0.55" />
      ))}
    </g>
  );
}
