/* ===================== 5. 影忍（輪郭が煙に溶ける影の忍） ===================== */
function ZkDark5Defs() {
  return (
    <defs>
      <linearGradient id="zkDark5Body" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#4E4068" /><stop offset="0.5" stopColor="#1E1530" /><stop offset="1" stopColor="#07040C" /></linearGradient>
      <linearGradient id="zkDark5Scarf" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#A870E8" /><stop offset="0.5" stopColor="#5A2E90" /><stop offset="1" stopColor="#2A1048" stopOpacity="0.2" /></linearGradient>
      <radialGradient id="zkDark5Smoke"><stop offset="0" stopColor="#6A4A98" stopOpacity="0.85" /><stop offset="0.6" stopColor="#3A2458" stopOpacity="0.5" /><stop offset="1" stopColor="#1A0E28" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkDark5Glow"><stop offset="0" stopColor="#FFFFFF" stopOpacity="0.9" /><stop offset="0.35" stopColor="#D8B0FF" stopOpacity="0.7" /><stop offset="1" stopColor="#8A4AD8" stopOpacity="0" /></radialGradient>
      <linearGradient id="zkDark5Fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#1E1530" /><stop offset="0.55" stopColor="#1E1530" stopOpacity="0.8" /><stop offset="1" stopColor="#3A2458" stopOpacity="0" /></linearGradient>
      <linearGradient id="zkDark5Blade" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.5" stopColor="#C4BCDC" /><stop offset="1" stopColor="#4A4262" /></linearGradient>
    </defs>
  );
}
