/* ===================== 6. 黒大狼（瞳に菫の炎） ===================== */
function ZkDark6Defs() {
  return (
    <defs>
      <linearGradient id="zkDark6Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#62547E" /><stop offset="0.5" stopColor="#261C38" /><stop offset="1" stopColor="#08050E" /></linearGradient>
      <linearGradient id="zkDark6Mane" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#4A3C66" /><stop offset="1" stopColor="#0E0918" /></linearGradient>
      <linearGradient id="zkDark6Flame" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#8A3AE0" /><stop offset="0.5" stopColor="#C890FF" /><stop offset="1" stopColor="#F8F0FF" stopOpacity="0.2" /></linearGradient>
      <radialGradient id="zkDark6Glow"><stop offset="0" stopColor="#FFFFFF" stopOpacity="0.9" /><stop offset="0.35" stopColor="#D8B0FF" stopOpacity="0.7" /><stop offset="1" stopColor="#8A4AD8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 目の炎：原点が目、右上へたなびく */
function ZkDark6EyeFlame({ x, y, r = 0, s = 1, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
      <circle r="4" fill="url(#zkDark6Glow)" />
      <g className="zk-flick" style={{ animationDelay: `${d}ms` }}>
        <path d="M-1 0 C2 -2 6 -4 9 -9 C9 -5 11 -3 13 -4 C11 0 6 2 0 1.6 Z" fill="url(#zkDark6Flame)" />
      </g>
    </g>
  );
}
function ZkDark6Sparks({ pts }) {
  return pts.map(([x, y, d], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r="1.2" fill="#E0C8FF" /><circle r="3" fill="url(#zkDark6Glow)" opacity="0.6" /></g></g>
  ));
}
