/* ---- zk:ghost ---- */
// ZKT/ghost.jsx — ゴースト（系統 dark）：提灯お化け／人魂／唐傘お化け／骸骨武者／がしゃどくろ／のっぺらぼう
/* ================= 2. 人魂：漂う魂（b1） ================= */
function ZkGhost2Defs() {
  return (
    <defs>
      <radialGradient id="zkGhost2Core" cx="0.36" cy="0.34" r="0.72"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.3" stopColor="#E8D8FF" /><stop offset="0.72" stopColor="#9A6AE0" /><stop offset="1" stopColor="#4A2090" /></radialGradient>
      <linearGradient id="zkGhost2Tail" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#C8A8FF" /><stop offset="0.5" stopColor="#7A48C8" stopOpacity="0.9" /><stop offset="1" stopColor="#3A1878" stopOpacity="0.15" /></linearGradient>
      <radialGradient id="zkGhost2Halo"><stop offset="0" stopColor="#C8A0FF" stopOpacity="0.5" /><stop offset="1" stopColor="#6A3A9A" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkGhost2Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#D8C0FF" /><stop offset="1" stopColor="#8A5AC8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkGhost2Motes({ pts }) {
  return pts.map(([x, y, d, r], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill="url(#zkGhost2Mote)" /></g></g>
  ));
}
function ZkGhost2S() {
  return (
    <g>
      <ZkGhost2Defs />
      <g className="zk-glow"><circle cx="40" cy="68" r="26" fill="url(#zkGhost2Halo)" /></g>
      {/* 尾：右上へ長く流れる（揺らめく） */}
      <g className="zk-flick">
        <path d="M26 64 C28 48 40 42 52 36 C62 31 70 24 76 16 C75 26 70 32 64 38 C72 36 80 32 88 28 C82 42 70 52 58 64 C54 72 50 80 44 84 Z" fill="url(#zkGhost2Tail)" stroke="#E0C8FF" strokeWidth="0.6" strokeOpacity="0.5" />
        <path d="M32 62 C38 52 48 46 58 40 C64 37 68 33 72 28 C68 38 60 46 52 56 Z" fill="#E8D8FF" opacity="0.45" />
      </g>
      <g className="zk-breathe"><g transform="rotate(-8 40 78)">
        {/* 魂の頭：左下へ突っ込む */}
        <path d="M23 70 C23 60 31 53 41 53 C51 53 58 60 58 69 C58 79 50 87 40 87 C30 87 23 80 23 70 Z" fill="url(#zkGhost2Core)" />
        <path d="M28 62 Q33 56 40 56" fill="none" stroke="#FFFFFF" strokeWidth="1.2" opacity="0.7" strokeLinecap="round" />
        {/* かすかな顔：目の洞と、細く開いた口 */}
        <path className="zk-blink" d="M27 68 Q31 63.8 35.6 66.6 Q31 70 27 68 Z" fill="#3A1466" />
        <circle cx="30" cy="67.2" r="0.9" fill="#F4E8FF" />
        <path d="M26 71 L31 70" stroke="#3A1466" strokeWidth="0.9" opacity="0.7" />
        <ellipse cx="27" cy="77" rx="1.8" ry="2.8" fill="#3A1466" opacity="0.85" />
      </g></g>
      <ZkGhost2Motes pts={[[14, 50, 0, 3.4], [18, 84, -1300, 2.6], [86, 46, -2100, 3]]} />
    </g>
  );
}
