// ZKT/psychic.jsx — エスパー（系統 dark）：目玉の精／占い猫／狐面の術士／浮面／割れ鏡の精／三眼梟
/* ================= 1. 目玉の精：羽の生えた目玉（b1） ================= */
function ZkPsychic1Defs() {
  return (
    <defs>
      <radialGradient id="zkPsychic1Ball" cx="0.36" cy="0.3" r="0.78"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.45" stopColor="#EEE6FA" /><stop offset="0.82" stopColor="#A48ED0" /><stop offset="1" stopColor="#4E3A80" /></radialGradient>
      <radialGradient id="zkPsychic1Iris" cx="0.42" cy="0.38" r="0.62"><stop offset="0" stopColor="#FFF4FF" /><stop offset="0.3" stopColor="#D09AFF" /><stop offset="0.75" stopColor="#7030C0" /><stop offset="1" stopColor="#2A0A50" /></radialGradient>
      <linearGradient id="zkPsychic1Wing" x1="0" y1="1" x2="0.8" y2="0"><stop offset="0" stopColor="#6A48A8" /><stop offset="0.5" stopColor="#B8A0E8" /><stop offset="1" stopColor="#F4ECFF" /></linearGradient>
      <linearGradient id="zkPsychic1Mist" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#D0A8FF" stopOpacity="0.9" /><stop offset="1" stopColor="#6A3A9A" stopOpacity="0" /></linearGradient>
      <radialGradient id="zkPsychic1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#D8C0FF" /><stop offset="1" stopColor="#8A5AC8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkPsychic1Wing({ t, d = 0, far }) {
  return (
    <g transform={t}><g className="zk-wing" style={{ animationDelay: `${d}ms` }}>
      <path d="M0 0 C2 -8 8 -16 18 -20 C24 -22 30 -22 33 -19 C29 -18 27 -16 28 -14 C32 -14 33 -11 30 -9.6 C26 -9.6 24 -8 25 -6 C28 -5 27.6 -2 24 -1.2 C18 1 8 2 0 0 Z" fill="url(#zkPsychic1Wing)" opacity={far ? 0.7 : 1} stroke="#E0C8FF" strokeWidth="0.6" strokeOpacity="0.6" />
      <path d="M4 -2 C10 -8 18 -13 28 -17 M6 -0.4 C12 -4 18 -6.6 27 -7.6" fill="none" stroke="#5A3A96" strokeWidth="0.6" opacity="0.55" />
    </g></g>
  );
}
function ZkPsychic1Motes({ pts }) {
  return pts.map(([x, y, d, r], i) => (
    <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill="url(#zkPsychic1Mote)" /></g></g>
  ));
}
