/* ================= 3. 狐面の術士：狐面の術者（b2） ================= */
function ZkPsychic3Defs() {
  return (
    <defs>
      <linearGradient id="zkPsychic3Robe" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#7E4CB8" /><stop offset="0.5" stopColor="#36185E" /><stop offset="1" stopColor="#120828" /></linearGradient>
      <linearGradient id="zkPsychic3Sleeve" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#9A66D8" /><stop offset="0.55" stopColor="#4A2278" /><stop offset="1" stopColor="#1A0A34" /></linearGradient>
      <linearGradient id="zkPsychic3Mask" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.55" stopColor="#ECE2F8" /><stop offset="1" stopColor="#9E8CC2" /></linearGradient>
      <linearGradient id="zkPsychic3Hair" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#4A3668" /><stop offset="1" stopColor="#0E0818" /></linearGradient>
      <linearGradient id="zkPsychic3Gold" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#E8C46A" /><stop offset="0.5" stopColor="#FFF0B0" /><stop offset="1" stopColor="#B8902A" /></linearGradient>
      <radialGradient id="zkPsychic3Orb"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.3" stopColor="#E8D4FF" /><stop offset="0.65" stopColor="#A060F0" stopOpacity="0.7" /><stop offset="1" stopColor="#6A3A9A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkPsychic3Orb({ x, y, r, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y})`}><g className="zk-glow" style={{ animationDelay: `${d}ms` }}>
      <circle r={r} fill="url(#zkPsychic3Orb)" />
      <path d={`M${-r * 0.9} 0 L${r * 0.9} 0 M0 ${-r * 0.9} L0 ${r * 0.9}`} stroke="#F4ECFF" strokeWidth="0.5" opacity="0.5" transform="rotate(45)" />
    </g></g>
  );
}
