const ZK_ART = {
  ground: ZK_T_ground,
  rock: ZK_T_rock,
  grass: ZK_T_grass,
  fire: ZK_T_fire,
  dragon: ZK_T_dragon,
  steel: ZK_T_steel,
  water: ZK_T_water,
  ice: ZK_T_ice,
  poison: ZK_T_poison,
  fly: ZK_T_fly,
  bug: ZK_T_bug,
  fairy: ZK_T_fairy,
  fight: ZK_T_fight,
  electric: ZK_T_electric,
  normal: ZK_T_normal,
  dark: ZK_T_dark,
  ghost: ZK_T_ghost,
  psychic: ZK_T_psychic,
};
/*
  【区分ボスの絵】2026-09-28（Aki）。18タイプ×3帯＝54種。区分の主（⑨の特大）だけに使う。
  ★ 雑魚より一回り強そうに：枠いっぱい・金の装身具・属性の気配・動きが二か所。
  ⚠️ 雑魚の進化形にしない（同じタイプの雑魚6体と別の生き物）。
  ★ ZKB_ART[type] は3体（b1,b2,b3）の [横,斜め,正面]。無い枠は雑魚の絵で代える。
*/
/* ==== ZKB_TYPES BEGIN ==== */
/* ---- zk:ground ---- */
// ZKT/boss_ground.jsx — じめん 区分ボス（系統 earth）
/* 共有：琥珀の光の粒（漂う）と砂の筋 */
function ZkBGroundMotes({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, r, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={fill} /></g></g>
      ))}
    </g>
  );
}
function ZkBGroundGusts({ lines }) {
  return (
    <g>
      {lines.map(([d, delay, op], i) => (
        <g key={i} className="zk-gust" style={{ animationDelay: `${delay}ms` }}><path d={d} fill="none" stroke="#E0C090" strokeWidth="0.8" opacity={op} strokeLinecap="round" /></g>
      ))}
    </g>
  );
}

/* ================= 1. 砂鰐の頭（b1） ================= */
function ZkBGround1Defs() {
  return (
    <defs>
      <linearGradient id="zkBGround1Hide" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D8B07A" /><stop offset="0.5" stopColor="#8E6038" /><stop offset="1" stopColor="#34200E" /></linearGradient>
      <linearGradient id="zkBGround1Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F4DEB0" /><stop offset="1" stopColor="#A8804E" /></linearGradient>
      <linearGradient id="zkBGround1Plate" x1="0.2" y1="0" x2="0.7" y2="1"><stop offset="0" stopColor="#F6DCAC" /><stop offset="0.5" stopColor="#B8844E" /><stop offset="1" stopColor="#5A3A1C" /></linearGradient>
      <linearGradient id="zkBGround1Sand" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#E8C898" /><stop offset="0.5" stopColor="#A87C4C" /><stop offset="1" stopColor="#6A4A2A" stopOpacity="0.4" /></linearGradient>
      <linearGradient id="zkBGround1Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#7A2A18" /><stop offset="1" stopColor="#1E0A06" /></linearGradient>
      <linearGradient id="zkBGround1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <radialGradient id="zkBGround1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFC870" /><stop offset="1" stopColor="#E0A040" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 背の砂岩の稜（低い鱗板を二列に並べる。[x, y, 角度, 大きさ]）
function ZkBGround1Ridge({ pts }) {
  return (
    <g>
      {pts.map(([x, y, r, s], i) => (
        <g key={i} transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
          <path d="M-3.6 1.2 L-2.8 -2.6 L-0.6 -4.4 L2 -3.8 L3.6 -0.6 L3.6 1.2 Z" fill="url(#zkBGround1Plate)" />
          <path d="M-0.6 -3.6 L0.2 0.6" stroke="#5A3A1C" strokeWidth="0.5" opacity="0.6" />
        </g>
      ))}
    </g>
  );
}
