/* ================= 3. 大地の陸竜（b3） ================= */
function ZkBGround3Defs() {
  return (
    <defs>
      <linearGradient id="zkBGround3Hide" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A8845E" /><stop offset="0.5" stopColor="#5A3E26" /><stop offset="1" stopColor="#1E130A" /></linearGradient>
      <linearGradient id="zkBGround3Hill" x1="0.2" y1="0" x2="0.6" y2="1"><stop offset="0" stopColor="#C8A070" /><stop offset="0.55" stopColor="#7A5634" /><stop offset="1" stopColor="#3A2614" /></linearGradient>
      <linearGradient id="zkBGround3Rock" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#E8D8BC" /><stop offset="0.5" stopColor="#9A8468" /><stop offset="1" stopColor="#4A3A2A" /></linearGradient>
      <linearGradient id="zkBGround3Tusk" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF8E4" /><stop offset="0.6" stopColor="#E0C898" /><stop offset="1" stopColor="#8A6A40" /></linearGradient>
      <linearGradient id="zkBGround3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBGround3Tree" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#8A7A48" /><stop offset="1" stopColor="#3A3018" /></linearGradient>
      <radialGradient id="zkBGround3Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFC870" /><stop offset="1" stopColor="#E0A040" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBGround3Aura"><stop offset="0" stopColor="#FFB850" stopOpacity="0.5" /><stop offset="1" stopColor="#A8744A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 背の丘（原点が丘の底の中心、幅 ±24）
function ZkBGround3Hill({ s = 1 }) {
  return (
    <g transform={`scale(${s})`}>
      <path d="M-24 0 C-22 -8 -16 -14 -8 -16 C-2 -22 8 -22 14 -16 C20 -12 24 -6 24 0 Z" fill="url(#zkBGround3Hill)" />
      {/* 若木（茶の幹、くすんだ葉） */}
      <path d="M10 -18 L10 -26" stroke="#4A3018" strokeWidth="1.2" />
      <path d="M10 -32 C14 -30 15 -26 12 -24 C10 -23 8 -23 6 -24 C4 -27 6 -31 10 -32 Z" fill="url(#zkBGround3Tree)" />
      {/* 岩 */}
      <path d="M-10 -14 L-8 -24 L-1 -27 L4 -20 L2 -14 Z" fill="url(#zkBGround3Rock)" />
      <path d="M-20 -4 L-18 -12 L-12 -13 L-10 -6 Z" fill="url(#zkBGround3Rock)" />
      <path d="M14 -10 L18 -16 L22 -12 L21 -5 Z" fill="url(#zkBGround3Rock)" />
      <path d="M-8 -22 L-2 -25" stroke="#FFF4DA" strokeWidth="0.8" opacity="0.6" />
      {/* 琥珀の亀裂 */}
      <g className="zk-shine"><path d="M-14 -2 L-8 -8 L-4 -6 L2 -12 M6 -4 L10 -9" fill="none" stroke="#FFC870" strokeWidth="1.2" strokeLinecap="round" /></g>
    </g>
  );
}
