/* ---- /zk:ground ---- */
/* ---- zk:rock ---- */
// ZKT/boss_rock.jsx — 区分ボス（いわ／系統 earth）
/* ---- 共有の小物 ---- */
// 琥珀に光る目（外側 g で位置、内側でまばたき）
function ZkBRockEye({ x, y, w = 2.6, h = 1.4, r = 0, glow }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r})`}>
      <ellipse rx={w * 1.9} ry={h * 2.6} fill={`url(#${glow})`} opacity="0.75" />
      <g className="zk-blink">
        <path d={`M${-w} ${h * 0.2} Q${-w * 0.1} ${-h * 1.5} ${w} ${-h * 0.5} Q${w * 0.1} ${h * 1.1} ${-w} ${h * 0.2} Z`} fill="#FFD27A" />
        <ellipse cx={-w * 0.12} cy={-h * 0.1} rx={w * 0.17} ry={h * 0.75} fill="#2A1404" />
      </g>
    </g>
  );
}
// 漂う琥珀の粒
function ZkBRockMotes({ pts, glow }) {
  return (
    <g>
      {pts.map(([x, y, r, d, k], i) => (
        <g key={i} transform={`translate(${x} ${y})`}>
          <g className={k || "zk-bob"} style={{ animationDelay: `${d}ms` }}>
            <circle r={r} fill={`url(#${glow})`} />
            <circle r={r * 0.28} fill="#FFF4D0" />
          </g>
        </g>
      ))}
    </g>
  );
}
// 漂う石のかけら
function ZkBRockChips({ pts }) {
  return (
    <g>
      {pts.map(([x, y, s, d], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${s})`}>
          <g className="zk-bob" style={{ animationDelay: `${d}ms` }}>
            <path d="M-2 0 L-0.6 -2 L1.8 -1.2 L2 0.8 L0 2 Z" fill="#8A6A48" stroke="#E0C090" strokeWidth="0.4" strokeOpacity="0.7" />
          </g>
        </g>
      ))}
    </g>
  );
}
// 風の筋（土の気）
function ZkBRockGust({ lines }) {
  return (
    <g>
      {lines.map(([d, delay], i) => (
        <g key={i} className="zk-gust" style={{ animationDelay: `${delay}ms` }}>
          <path d={d} fill="none" stroke="#E0C090" strokeWidth="0.8" opacity="0.6" strokeLinecap="round" />
        </g>
      ))}
    </g>
  );
}

/* ======================= b1 岩山羊の頭領 ======================= */
function ZkBRock1Defs() {
  return (
    <defs>
      <linearGradient id="zkBRock1Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#F2DCB4" /><stop offset="0.5" stopColor="#B08458" /><stop offset="1" stopColor="#4A3020" /></linearGradient>
      <linearGradient id="zkBRock1FurDk" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#8A6440" /><stop offset="1" stopColor="#2E1C10" /></linearGradient>
      <linearGradient id="zkBRock1Beard" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFF4DC" /><stop offset="1" stopColor="#C8A478" /></linearGradient>
      <linearGradient id="zkBRock1Horn" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#EADCC4" /><stop offset="0.5" stopColor="#9A8468" /><stop offset="1" stopColor="#3E3024" /></linearGradient>
      <linearGradient id="zkBRock1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBRock1Crag" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A89078" /><stop offset="0.5" stopColor="#5A4838" /><stop offset="1" stopColor="#221A14" /></linearGradient>
      <radialGradient id="zkBRock1Glow"><stop offset="0" stopColor="#FFE6A8" stopOpacity="0.95" /><stop offset="1" stopColor="#E0A040" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 石の巻き角（根元が原点、後ろ上へ伸びて巻く）
function ZkBRock1Horn({ dark }) {
  const a = "M0 0 C2 -9 10 -14 18 -12";
  const b = "M18 -12 C26 -10 29 -1 25 6";
  const c = "M25 6 C21 12 13 10 13 4 C13 0 17 -1 19 1";
  const g = dark ? "#5A4A3A" : "url(#zkBRock1Horn)";
  return (
    <g>
      <path d={a} fill="none" stroke={g} strokeWidth="7.4" strokeLinecap="round" />
      <path d={b} fill="none" stroke={g} strokeWidth="5.8" strokeLinecap="round" />
      <path d={c} fill="none" stroke={g} strokeWidth="4" strokeLinecap="round" />
      <path d={a} fill="none" stroke="#2A1E14" strokeWidth="6.6" strokeDasharray="0.7 2.3" opacity="0.4" />
      <path d={b} fill="none" stroke="#2A1E14" strokeWidth="5" strokeDasharray="0.7 2.1" opacity="0.4" />
      <path d={c} fill="none" stroke="#2A1E14" strokeWidth="3.2" strokeDasharray="0.6 1.8" opacity="0.4" />
      {!dark && <path d="M1 -3 C4 -10 11 -13 18 -12.6 C24 -11.6 27 -6 27 -1" fill="none" stroke="#FFF6E4" strokeWidth="0.9" opacity="0.6" strokeLinecap="round" />}
      <path d={a} pathLength="100" fill="none" stroke="url(#zkBRock1Gold)" strokeWidth="8" strokeDasharray="7 93" strokeDashoffset="-58" />
      <path d={b} pathLength="100" fill="none" stroke="url(#zkBRock1Gold)" strokeWidth="6.4" strokeDasharray="8 92" strokeDashoffset="-46" />
    </g>
  );
}
