      <linearGradient id="zkBRock2Horn" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#5A4636" /><stop offset="0.55" stopColor="#B8A488" /><stop offset="1" stopColor="#F0E4CC" /></linearGradient>
