/* ======================= b3 水晶窟の巨竜 ======================= */
function ZkBRock3Defs() {
  return (
    <defs>
      <linearGradient id="zkBRock3Hide" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#9A7C60" /><stop offset="0.5" stopColor="#4E3A2A" /><stop offset="1" stopColor="#1C120A" /></linearGradient>
      <linearGradient id="zkBRock3Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#D8B488" /><stop offset="1" stopColor="#6A4A30" /></linearGradient>
      <linearGradient id="zkBRock3Crys" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#B8601E" /><stop offset="0.55" stopColor="#FFB850" /><stop offset="1" stopColor="#FFF6D8" /></linearGradient>
      <linearGradient id="zkBRock3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBRock3Horn" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#3A2A1C" /><stop offset="1" stopColor="#D8C4A4" /></linearGradient>
      <radialGradient id="zkBRock3Glow"><stop offset="0" stopColor="#FFE6A8" stopOpacity="0.95" /><stop offset="1" stopColor="#E0A040" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBRock3Aura"><stop offset="0" stopColor="#FFB850" stopOpacity="0.4" /><stop offset="1" stopColor="#E08030" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBRock3Fire"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFD27A" /><stop offset="1" stopColor="#E07020" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 水晶の柱（原点が根元、上へ伸びる）
function ZkBRock3Shard({ x, y, len, w = 2.6, r = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r})`}>
      <path d={`M${-w} 0 L${-w * 0.9} ${-len * 0.78} L0 ${-len} L${w * 0.9} ${-len * 0.78} L${w} 0 Z`} fill="url(#zkBRock3Crys)" stroke="#7A3A10" strokeWidth="0.35" />
      <path d={`M0 0 L0 ${-len} L${w * 0.9} ${-len * 0.78} L${w} 0 Z`} fill="#6A2A08" opacity="0.28" />
      <path d={`M${-w * 0.5} ${-len * 0.1} L${-w * 0.45} ${-len * 0.72}`} stroke="#FFFBEA" strokeWidth="0.6" opacity="0.8" />
    </g>
  );
}
// 水晶の翼：肩（原点）から扇形に伸びる柱の房
function ZkBRock3Wing({ s = 1, dim }) {
  const shards = [[0, 0, 34, 3.4, 20], [0, 0, 30, 3.2, 38], [0, 0, 25, 3, 56], [0, 0, 19, 2.8, 74], [2, 2, 14, 2.4, 92]];
  return (
    <g transform={`scale(${s})`} opacity={dim ? 0.8 : 1}>
      <path d="M0 0 C8 -18 22 -30 32 -30 C30 -18 28 -6 20 6 C12 8 5 6 0 4 Z" fill="#2A1C12" stroke="#E0A040" strokeWidth="0.7" strokeOpacity="0.65" />
      {shards.map(([x, y, l, w, r], i) => <ZkBRock3Shard key={i} x={x} y={y} len={l} w={w} r={r} />)}
    </g>
  );
}
