/* ---- /zk:rock ---- */
/* ---- zk:grass ---- */
// ZKT/boss_grass.jsx — くさの区分ボス（系統 earth）。緑は抑え、木肌の茶と琥珀の光で。
/* 共有：琥珀の光の粒（漂う） */
function ZkBGrassMotes({ id, pts }) {
  return (
    <g>
      {pts.map(([x, y, d, r], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={`url(#${id})`} /></g></g>
      ))}
    </g>
  );
}
/* 共有：琥珀の光の筋（流れる） */
function ZkBGrassStreaks({ pts }) {
  return (
    <g>
      {pts.map(([x, y, w, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-gust" style={{ animationDelay: `${d}ms` }}>
          <path d={`M0 0 Q${w / 2} -2 ${w} 0`} fill="none" stroke="#FFD27A" strokeWidth="0.7" strokeLinecap="round" opacity="0.7" />
        </g></g>
      ))}
    </g>
  );
}

/* ================= 1. 切り株の番人（b1：群れの親分） ================= */
function ZkBGrass1Defs() {
  return (
    <defs>
      <linearGradient id="zkBGrass1Bark" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#D0A070" /><stop offset="0.5" stopColor="#7E5030" /><stop offset="1" stopColor="#2E1A0C" /></linearGradient>
      <linearGradient id="zkBGrass1BarkD" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#7A5232" /><stop offset="1" stopColor="#2A180C" /></linearGradient>
      <radialGradient id="zkBGrass1Top" cx="0.45" cy="0.45"><stop offset="0" stopColor="#F0D2A0" /><stop offset="0.6" stopColor="#C8945E" /><stop offset="1" stopColor="#7A4E2C" /></radialGradient>
      <linearGradient id="zkBGrass1Moss" x1="0.2" y1="0" x2="0.6" y2="1"><stop offset="0" stopColor="#B8AC6A" /><stop offset="0.5" stopColor="#6E6836" /><stop offset="1" stopColor="#302E16" /></linearGradient>
      <linearGradient id="zkBGrass1Stone" x1="0.1" y1="0" x2="0.9" y2="1"><stop offset="0" stopColor="#D8D0C0" /><stop offset="0.5" stopColor="#8A8274" /><stop offset="1" stopColor="#3A342C" /></linearGradient>
      <linearGradient id="zkBGrass1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#A8801E" /></linearGradient>
      <radialGradient id="zkBGrass1Eye"><stop offset="0" stopColor="#FFC850" stopOpacity="0.85" /><stop offset="1" stopColor="#FF9A20" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBGrass1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#FFD27A" /><stop offset="1" stopColor="#E0A040" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
/* 石頭の斧：握りが原点、柄は上へ、刃は左へ */
