/* ---- /zk:grass ---- */
/* ---- zk:fire ---- */
// ZKT/boss_fire.jsx — ほのお 区分ボス（系統 fire）
/* 共有：漂う火の粉（zk-bob）、立ちのぼる火花（zk-bfire-rise）、炎の舌 */
function ZkBFireMotes({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, r, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={fill} /></g></g>
      ))}
    </g>
  );
}
function ZkBFireEmbers({ pts }) {
  return (
    <g>
      {pts.map(([x, y, d, s = 1], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-bfire-rise" style={{ animationDelay: `${d}ms` }}>
          <path d="M0 -1.8 L0.9 0 L0 1.8 L-0.9 0 Z" fill="#FFE08A" />
        </g></g>
      ))}
    </g>
  );
}
// 炎の舌（根元 0,0・上向き・高さ20）。[x, y, 角度, 大きさ, 遅れ]
function ZkBFireFlames({ pts, fill, cls, core = "#FFF0A0" }) {
  return (
    <g>
      {pts.map(([x, y, r, s, d = 0], i) => (
        <g key={i} transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
          <g className={cls} style={cls ? { animationDelay: `${d}ms` } : undefined}>
            <path d="M0 0 C-5 -1 -6 -6 -3 -10 C-2 -7 -1 -7 -1 -9 C-1 -13 1 -16 0 -20 C4 -16 6 -10 5 -5 C6 -6 6 -8 6 -9 C8 -5 6 -1 0 0 Z" fill={fill} />
            <path d="M0 -1 C-3 -2 -3 -5 -1 -8 C0 -6 1 -8 1 -11 C3 -8 4 -4 0 -1 Z" fill={core} opacity="0.85" />
          </g>
        </g>
      ))}
    </g>
  );
}

/* ================= 1. 火車（b1）：燃える車を引く黒い大猫 ================= */
function ZkBFire1Defs() {
  return (
    <defs>
      <linearGradient id="zkBFire1Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#6E3A48" /><stop offset="0.45" stopColor="#2C1220" /><stop offset="1" stopColor="#10060A" /></linearGradient>
      <linearGradient id="zkBFire1Flame" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#C8321E" /><stop offset="0.5" stopColor="#FF8A3A" /><stop offset="1" stopColor="#FFE08A" /></linearGradient>
      <linearGradient id="zkBFire1Wood" x1="0" y1="0" x2="0.4" y2="1"><stop offset="0" stopColor="#8A4424" /><stop offset="0.6" stopColor="#4A1C0E" /><stop offset="1" stopColor="#220A06" /></linearGradient>
      <linearGradient id="zkBFire1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBFire1Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#B8281A" /><stop offset="1" stopColor="#3A0806" /></linearGradient>
      <radialGradient id="zkBFire1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFC060" /><stop offset="1" stopColor="#FF5A2A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
function ZkBFire1Wheel({ rx = 9, ry = 9 }) {
  return (
    <g>
      <ellipse rx={rx} ry={ry} fill="none" stroke="url(#zkBFire1Wood)" strokeWidth="2.6" />
      <ellipse rx={rx} ry={ry} fill="none" stroke="#FF6A3A" strokeWidth="0.6" opacity="0.7" />
      {[0, 60, 120].map((a) => (
        <path key={a} d={`M${-Math.cos(a * Math.PI / 180) * rx} ${-Math.sin(a * Math.PI / 180) * ry} L${Math.cos(a * Math.PI / 180) * rx} ${Math.sin(a * Math.PI / 180) * ry}`} stroke="#4A1C0E" strokeWidth="1.3" />
      ))}
      <ellipse rx={rx * 0.26} ry={ry * 0.26} fill="url(#zkBFire1Gold)" />
    </g>
  );
}
