        <g transform="translate(44 89.4)"><g className="zk-flick" style={{ animationDelay: "-400ms" }}>
          <path d="M0 -1.6 C-6 -1.6 -12 -2 -16 -5 C-18 -7 -20 -6 -19 -4 C-16 0 -8 2 0 1.8 Z" fill="url(#zkBDragon2Hide)" />
          <path d="M-18 -4.6 L-23 -8 L-20 -2 Z" fill="url(#zkBDragon2Horn)" />
        </g></g>
