/* ================= 3. 歩く城塞（b3：伝説の怪物） ================= */
function ZkBSteel3Defs() {
  return (
    <defs>
      <linearGradient id="zkBSteel3Iron" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A8B0C0" /><stop offset="0.4" stopColor="#484C5A" /><stop offset="1" stopColor="#0F1015" /></linearGradient>
      <linearGradient id="zkBSteel3Dark" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#4C5062" /><stop offset="1" stopColor="#0B0C10" /></linearGradient>
      <linearGradient id="zkBSteel3Wall" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#8A92A2" /><stop offset="0.5" stopColor="#3E4250" /><stop offset="1" stopColor="#16171D" /></linearGradient>
      <linearGradient id="zkBSteel3Roof" x1="0.2" y1="0" x2="0.9" y2="1"><stop offset="0" stopColor="#6A6E80" /><stop offset="1" stopColor="#15161C" /></linearGradient>
      <linearGradient id="zkBSteel3Brass" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFEAB0" /><stop offset="0.5" stopColor="#D89C3A" /><stop offset="1" stopColor="#6A3E12" /></linearGradient>
      <linearGradient id="zkBSteel3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF4C0" /><stop offset="0.5" stopColor="#F0C860" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBSteel3Tusk" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF6DC" /><stop offset="0.5" stopColor="#E8C080" /><stop offset="1" stopColor="#8A5A20" /></linearGradient>
      <linearGradient id="zkBSteel3Fire" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#FFF4C0" /><stop offset="0.45" stopColor="#FF9A30" /><stop offset="1" stopColor="#C8321E" /></linearGradient>
      <linearGradient id="zkBSteel3Flag" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#E8483A" /><stop offset="1" stopColor="#FFB040" /></linearGradient>
      <radialGradient id="zkBSteel3Hot"><stop offset="0" stopColor="#FFF4C8" /><stop offset="0.35" stopColor="#FFB040" stopOpacity="0.8" /><stop offset="1" stopColor="#E8483A" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBSteel3Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#FFB040" /><stop offset="1" stopColor="#E8483A" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 城壁（x1〜x2、上端 y、下端 b）。胸壁の縁は金
function ZkBSteel3Wall({ x1, x2, y, b, n = 6 }) {
  const w = (x2 - x1) / (n * 2 - 1);
  let d = `M${x1} ${b} L${x1} ${y - 3}`;
  for (let i = 0; i < n * 2 - 1; i++) {
    const xa = x1 + w * i, xb = xa + w;
    d += i % 2 === 0 ? ` L${xb.toFixed(2)} ${y - 3}` : ` L${xa.toFixed(2)} ${y} L${xb.toFixed(2)} ${y} L${xb.toFixed(2)} ${y - 3}`;
  }
  d += ` L${x2} ${b} Z`;
  return (
    <g>
      <path d={d} fill="url(#zkBSteel3Wall)" {...ZK_BSTEEL_RIM} />
      <path d={`M${x1} ${y + 1} L${x2} ${y + 1}`} stroke="url(#zkBSteel3Gold)" strokeWidth="1.3" />
      <path d={`M${x1} ${(y + b) / 2 + 1} L${x2} ${(y + b) / 2 + 1}`} stroke="#15161C" strokeWidth="0.6" opacity="0.6" />
    </g>
  );
}
// 塔（中心 x、屋根の先 top、塔身の上 y、下 b、幅 w）。窓は炉の光
function ZkBSteel3Tower({ x, top, y, b, w, win = 2, dl = "0ms" }) {
  const h = w / 2;
  const wins = [];
  for (let i = 0; i < win; i++) wins.push(y + 4 + i * 6);
  return (
    <g>
      <path d={`M${x - h} ${b} L${x - h} ${y} L${x + h} ${y} L${x + h} ${b} Z`} fill="url(#zkBSteel3Wall)" {...ZK_BSTEEL_RIM} />
      <path d={`M${x - h + 1} ${y + 1} L${x - h + 1} ${b}`} stroke="#E4EAF4" strokeWidth="0.8" opacity="0.4" />
      <path d={`M${x - h - 1.6} ${y + 0.6} L${x} ${top} L${x + h + 1.6} ${y + 0.6} Z`} fill="url(#zkBSteel3Roof)" {...ZK_BSTEEL_RIM} />
      <path d={`M${x - h - 1.6} ${y + 0.6} L${x + h + 1.6} ${y + 0.6}`} stroke="url(#zkBSteel3Gold)" strokeWidth="1.2" />
      <circle cx={x} cy={top} r="0.9" fill="url(#zkBSteel3Gold)" />
      <g className="zk-shine" style={{ animationDelay: dl }}>
        {wins.map((wy, i) => (
          <g key={i}>
            <circle cx={x} cy={wy + 1} r="2.6" fill="url(#zkBSteel3Hot)" opacity="0.7" />
            <path d={`M${x - 0.9} ${wy + 2.4} L${x - 0.9} ${wy} C${x - 0.9} ${wy - 1.2} ${x + 0.9} ${wy - 1.2} ${x + 0.9} ${wy} L${x + 0.9} ${wy + 2.4} Z`} fill="#FFC060" />
          </g>
        ))}
      </g>
    </g>
  );
}
// 旗（竿の根元 x,y）。⚠️ はためく
function ZkBSteel3Flag({ x, y, len = 7, flip }) {
  return (
    <g>
      <path d={`M${x} ${y} L${x} ${y - len}`} stroke="url(#zkBSteel3Gold)" strokeWidth="0.8" />
      <g transform={`translate(${x} ${y - len}) scale(${flip ? -1 : 1} 1)`}><g className="zk-flick">
        <path d="M0 0 C3 -1 7 1 11 0 L8 2.4 L11 4.6 C7 5.4 3 3.6 0 4.4 Z" fill="url(#zkBSteel3Flag)" />
      </g></g>
    </g>
  );
}
// 胴の炉の排気口（斜めのスリット）
function ZkBSteel3Vents({ x, y, n = 3, gap = 4.4, h = 7, dl = "0ms" }) {
  const items = [];
  for (let i = 0; i < n; i++) items.push(x + i * gap);
  return (
    <g>
      <ellipse cx={x + (n - 1) * gap / 2} cy={y + h / 2} rx={n * gap * 0.7} ry={h} fill="url(#zkBSteel3Hot)" opacity="0.5" />
      {items.map((vx, i) => (
        <g key={i}>
          <path d={`M${vx - 1.4} ${y} L${vx + 1.4} ${y} L${vx + 0.4} ${y + h} L${vx - 2.4} ${y + h} Z`} fill="#1A0E08" stroke="#E8B860" strokeWidth="0.4" />
          <g className="zk-glow" style={{ animationDelay: `${i * -400}ms` }}>
            <path d={`M${vx - 0.8} ${y + 0.8} L${vx + 0.6} ${y + 0.8} L${vx - 0.2} ${y + h - 0.8} L${vx - 1.6} ${y + h - 0.8} Z`} fill="url(#zkBSteel3Fire)" />
          </g>
        </g>
      ))}
    </g>
  );
}
// 肩・腰の大鎧板（中心 x,y、大きさ k、傾き r）
function ZkBSteel3Pauldron({ x, y, k = 1, r = 0, fx = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k * fx} ${k})`}>
      <path d="M-11 2 C-10 -7 0 -11 9 -7 C13 -4 13 4 10 9 C4 12 -6 12 -10 8 Z" fill="url(#zkBSteel3Iron)" {...ZK_BSTEEL_RIM} />
      <path d="M-9 4 C-4 7 4 7 10 3" fill="none" stroke="#15161C" strokeWidth="0.8" opacity="0.7" />
      <path d="M-8 -3 C-3 0 4 0 11 -3" fill="none" stroke="#15161C" strokeWidth="0.7" opacity="0.5" />
      <path d="M-10 8 C-6 12 4 12 10 9" fill="none" stroke="url(#zkBSteel3Gold)" strokeWidth="1.4" strokeLinecap="round" />
      <path d="M-7 -5 C-3 -8.4 3 -9 7 -7" fill="none" stroke="#E4EAF4" strokeWidth="1" opacity="0.55" strokeLinecap="round" />
      <circle cx="0" cy="1.6" r="1.1" fill="#E8B860" stroke="#5A3410" strokeWidth="0.3" />
    </g>
  );
}
// 太い脚（上端中心 x,y、足裏 b、幅 w）。爪は真鍮
function ZkBSteel3Leg({ x, y, b, w = 15, far }) {
  const h = w / 2;
  return (
    <g>
      <path d={`M${x - h} ${y} C${x - h - 2} ${y + (b - y) * 0.45} ${x - h + 1} ${b - 8} ${x - h - 1} ${b} L${x + h + 1} ${b} C${x + h - 1} ${b - 8} ${x + h + 1} ${y + (b - y) * 0.45} ${x + h} ${y} Z`} fill={far ? "url(#zkBSteel3Dark)" : "url(#zkBSteel3Iron)"} {...ZK_BSTEEL_RIM} />
      {!far && <path d={`M${x - h + 2} ${y + 3} C${x - h + 1} ${y + 10} ${x - h + 2.4} ${b - 10} ${x - h + 1.4} ${b - 4}`} fill="none" stroke="#E4EAF4" strokeWidth="0.9" opacity="0.4" />}
      <path d={`M${x - h - 0.6} ${(y + b) / 2 + 2} C${x - 2} ${(y + b) / 2 + 4} ${x + 2} ${(y + b) / 2 + 4} ${x + h + 0.6} ${(y + b) / 2 + 2}`} fill="none" stroke={far ? "#6A4A20" : "url(#zkBSteel3Gold)"} strokeWidth="1.3" />
      <path d={`M${x - h - 1} ${b - 5} L${x + h + 1} ${b - 5}`} stroke="#15161C" strokeWidth="0.7" opacity="0.6" />
      {[-0.66, 0, 0.66].map((t, i) => (
        <path key={i} d={`M${x + t * h - 2} ${b} L${x + t * h - 1.4} ${b - 2.6} L${x + t * h + 1.6} ${b - 2.6} L${x + t * h + 2} ${b} Z`} fill={far ? "#6A4A20" : "url(#zkBSteel3Brass)"} />
      ))}
    </g>
  );
}
