      <ZkBWaterMotes fill="url(#zkBWater3Mote)" pts={[[14, 30, 2.6, 0], [28, 12, 2, -1300], [80, 18, 2.6, -700], [92, 44, 2.2, -2100], [8, 52, 2.4, -1600], [88, 60, 1.8, -2600], [70, 44, 2, -900]]} />
