/* ---- /zk:water ---- */
/* ---- zk:ice ---- */
// ZKT/boss_ice.jsx — こおり 区分ボス（系統 water）
/* 共有：漂う雪の光（zk-bob）、きらめく氷片（zk-shine）、凍る息（zk-bice-puff）、氷柱のとげ */
function ZkBIceMotes({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, r, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={fill} /></g></g>
      ))}
    </g>
  );
}
function ZkBIceSparks({ pts }) {
  return (
    <g>
      {pts.map(([x, y, s, d], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-shine" style={{ animationDelay: `${d}ms` }}>
          <path d="M0 -2.6 L0.9 0 L0 2.6 L-0.9 0 Z" fill="#EAF8FF" />
        </g></g>
      ))}
    </g>
  );
}
// 凍る息：原点が口、-x 方向へ渦を巻いて広がる
function ZkBIceBreath({ fill, d = 0, origin }) {
  return (
    <g className="zk-bice-puff" style={origin ? { animationDelay: `${d}ms`, transformOrigin: origin } : { animationDelay: `${d}ms` }}>
      <ellipse cx="-7" cy="1" rx="8" ry="5" fill={fill} opacity="0.7" />
      <path d="M0 0 C-4 -3.4 -9.6 -3.2 -11.4 0 C-13 3 -10.6 6 -7.8 5.2 C-5.8 4.6 -6 2.2 -8 2.2" fill="none" stroke="#EAF8FF" strokeWidth="1.3" strokeLinecap="round" opacity="0.9" />
      <path d="M-1 1.6 C-3 4 -3.6 7 -2 9" fill="none" stroke="#9AD8FF" strokeWidth="0.9" strokeLinecap="round" opacity="0.75" />
      <circle cx="-13" cy="-4" r="1.3" fill="#DDF4FF" opacity="0.7" />
      <circle cx="-6" cy="-5" r="0.9" fill="#FFFFFF" opacity="0.8" />
      <circle cx="-10" cy="8" r="1" fill="#DDF4FF" opacity="0.7" />
    </g>
  );
}
// 吹雪の筋（zk-gust）：[x, y, 長さ, 遅れ]
function ZkBIceGusts({ pts }) {
  return (
    <g>
      {pts.map(([x, y, l, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-gust" style={{ animationDelay: `${d}ms` }}>
          <path d={`M0 0 Q${l / 2} -2 ${l} 0`} fill="none" stroke="#DDF4FF" strokeWidth="0.8" strokeLinecap="round" opacity="0.7" />
        </g></g>
      ))}
    </g>
  );
}
// 氷柱のとげ：[x, y, 角度, 長さ]
function ZkBIceSpikes({ pts, fill, w = 1.6 }) {
  return (
    <g>
      {pts.map(([x, y, r, l], i) => (
        <path key={i} transform={`translate(${x} ${y}) rotate(${r})`} d={`M${-w} 0 L0 ${-l} L${w} 0 Z`} fill={fill} stroke="#DDF4FF" strokeWidth="0.35" strokeOpacity="0.8" />
      ))}
    </g>
  );
}

/* ================= 1. 白熊の戦士（b1）：氷の棍棒を担ぐ群れの親分 ================= */
function ZkBIce1Defs() {
  return (
    <defs>
      <linearGradient id="zkBIce1Fur" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.45" stopColor="#CFE4F4" /><stop offset="1" stopColor="#5E86BC" /></linearGradient>
      <linearGradient id="zkBIce1Far" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#A8C4E0" /><stop offset="0.6" stopColor="#4A6A9C" /><stop offset="1" stopColor="#22365E" /></linearGradient>
      <linearGradient id="zkBIce1Club" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#A8E0FF" /><stop offset="0.75" stopColor="#3A8AE8" /><stop offset="1" stopColor="#1A3A7A" /></linearGradient>
      <linearGradient id="zkBIce1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBIce1Strap" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#5A6E9E" /><stop offset="1" stopColor="#222C52" /></linearGradient>
      <linearGradient id="zkBIce1Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#3A2A5A" /><stop offset="1" stopColor="#0E0A1E" /></linearGradient>
      <radialGradient id="zkBIce1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#BDEBFF" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
