/* ================= 3. 氷晶の竜（b3）：切子の結晶でできた大竜 ================= */
function ZkBIce3Defs() {
  return (
    <defs>
      <linearGradient id="zkBIce3Body" x1="0.15" y1="0" x2="0.85" y2="1"><stop offset="0" stopColor="#E4F6FF" /><stop offset="0.35" stopColor="#8CC8F4" /><stop offset="0.7" stopColor="#3470C8" /><stop offset="1" stopColor="#162A64" /></linearGradient>
      <linearGradient id="zkBIce3Far" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#7AB0E4" /><stop offset="1" stopColor="#14265A" /></linearGradient>
      <linearGradient id="zkBIce3Wing" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#1E4A9A" stopOpacity="0.9" /><stop offset="0.6" stopColor="#6AB0F0" stopOpacity="0.8" /><stop offset="1" stopColor="#EAF8FF" stopOpacity="0.9" /></linearGradient>
      <linearGradient id="zkBIce3Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F4FCFF" /><stop offset="1" stopColor="#9ED0F0" /></linearGradient>
      <linearGradient id="zkBIce3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBIce3Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#1E3A7A" /><stop offset="1" stopColor="#0A1030" /></linearGradient>
      <radialGradient id="zkBIce3Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#BDEBFF" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
