/* ---- zk:poison ---- */
// ZKT/boss_poison.jsx — どく 区分ボス（系統 water：深い青緑に紫の斑点を少し）
/* 共有：漂う毒の粒（zk-bob）、吐き出す毒霧（zk-bpoison-mist） */
function ZkBPoisonMotes({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, r, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={fill} /></g></g>
      ))}
    </g>
  );
}
// 毒霧のかたまり。[x, y, 大きさ, 遅れ]。左上へ流れて消える
function ZkBPoisonMist({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, s, d], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-bpoison-mist" style={{ animationDelay: `${d}ms` }}>
          <circle cx="0" cy="0" r="4" fill={fill} /><circle cx="3.6" cy="1.4" r="3" fill={fill} /><circle cx="-2.6" cy="2" r="2.6" fill={fill} />
        </g></g>
      ))}
    </g>
  );
}
// 斑点（毒のこぶ・模様）。[x, y, r]
function ZkBPoisonSpots({ pts, fill, op = 1 }) {
  return <g opacity={op}>{pts.map(([x, y, r], i) => <circle key={i} cx={x} cy={y} r={r} fill={fill} />)}</g>;
}

/* ================= 1. 大蝦蟇（b1）：毒のこぶを背負った大きな蝦蟇 ================= */
function ZkBPoison1Defs() {
  return (
    <defs>
      <linearGradient id="zkBPoison1Skin" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#469486" /><stop offset="0.5" stopColor="#15484C" /><stop offset="1" stopColor="#081C20" /></linearGradient>
      <linearGradient id="zkBPoison1Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#D2E4BC" /><stop offset="1" stopColor="#6E9A84" /></linearGradient>
      <linearGradient id="zkBPoison1Gland" x1="0" y1="0" x2="0.6" y2="1"><stop offset="0" stopColor="#5AA898" /><stop offset="1" stopColor="#163E42" /></linearGradient>
      <radialGradient id="zkBPoison1Wart" cx="0.4" cy="0.35"><stop offset="0" stopColor="#E4FFF6" /><stop offset="0.45" stopColor="#5ECAB4" /><stop offset="1" stopColor="#1A5A58" /></radialGradient>
      <radialGradient id="zkBPoison1WartV" cx="0.4" cy="0.35"><stop offset="0" stopColor="#F2E0FF" /><stop offset="0.45" stopColor="#A868DC" /><stop offset="1" stopColor="#4A1E78" /></radialGradient>
      <linearGradient id="zkBPoison1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBPoison1Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#3E1A48" /><stop offset="1" stopColor="#10060F" /></linearGradient>
      <radialGradient id="zkBPoison1Mist"><stop offset="0" stopColor="#D8FFF0" stopOpacity="0.95" /><stop offset="0.55" stopColor="#6AD8BC" stopOpacity="0.6" /><stop offset="1" stopColor="#3A8A80" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBPoison1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#8AE8FF" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBPoison1MoteV"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#C89AF0" /><stop offset="1" stopColor="#7A3AB0" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
const ZK_BPOISON1_SKIN = { fill: "url(#zkBPoison1Skin)", stroke: "#6ADCC8", strokeWidth: 0.7, strokeOpacity: 0.6 };
// 目：水色に鋭く光る（横長の瞳）。inner=-1 で目頭が左、1 で右（眉は目頭側へ下がる）
function ZkBPoison1Eye({ cx, cy, w = 5, tilt = 0, far = false, inner = -1 }) {
  const h = far ? 1.8 : 2.6;
  return (
    <g transform={`translate(${cx} ${cy}) rotate(${tilt}) scale(${-inner} 1)`}>
      <ellipse rx={w + 2} ry={h + 2} fill="url(#zkBPoison1Mote)" opacity="0.9" />
      <path className="zk-blink" d={`M${-w} ${h * 0.35} L${w} ${-h * 0.9} Q${w * 0.7} ${h * 0.9} ${-w} ${h * 0.35} Z`} fill="#C4F6FF" />
      <ellipse cx={w * 0.12} cy={-h * 0.05} rx={w * 0.34} ry={far ? 0.45 : 0.7} fill="#04161E" />
      <path d={`M${-w - 1.4} ${h * 0.1} L${w + 1} ${-h * 1.2} L${w + 0.6} ${-h * 1.9} Z`} fill="#061618" />
    </g>
  );
}
// 金の腕輪（腕に巻いた帯）
function ZkBPoison1Ring({ x, y, r = 0, rx = 4.6 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r})`}>
      <path d={`M${-rx} 0 A${rx} 1.6 0 0 1 ${rx} 0`} fill="none" stroke="#7A5412" strokeWidth="1.4" />
      <path d={`M${-rx} 0 A${rx} 1.8 0 0 0 ${rx} 0`} fill="none" stroke="url(#zkBPoison1Gold)" strokeWidth="2.6" />
      <path d={`M${-rx * 0.6} 1.2 A${rx} 1.8 0 0 0 ${rx * 0.4} 1.4`} fill="none" stroke="#FFF6D0" strokeWidth="0.6" />
    </g>
  );
}
