/* ================= 2. 絡新婦（b2）：女郎蜘蛛の妖。着物をきちんと着た妖しく美しい女、背に蜘蛛の脚 ================= */
function ZkBPoison2Defs() {
  return (
    <defs>
      <linearGradient id="zkBPoison2Kimono" x1="0.2" y1="0" x2="0.7" y2="1"><stop offset="0" stopColor="#2E7274" /><stop offset="0.45" stopColor="#123C42" /><stop offset="1" stopColor="#081A20" /></linearGradient>
      <linearGradient id="zkBPoison2Sleeve" x1="0" y1="0" x2="0.4" y2="1"><stop offset="0" stopColor="#246266" /><stop offset="1" stopColor="#0A2228" /></linearGradient>
      <linearGradient id="zkBPoison2Skin" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#F6FAF6" /><stop offset="1" stopColor="#B8D4D0" /></linearGradient>
      <linearGradient id="zkBPoison2Hair" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#34505A" /><stop offset="0.5" stopColor="#141E26" /><stop offset="1" stopColor="#080C12" /></linearGradient>
      <linearGradient id="zkBPoison2Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBPoison2Obi" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F2D890" /><stop offset="0.5" stopColor="#C89A40" /><stop offset="1" stopColor="#7A5418" /></linearGradient>
      <radialGradient id="zkBPoison2Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#8AE8FF" /><stop offset="1" stopColor="#3A8AE8" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBPoison2MoteV"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#C89AF0" /><stop offset="1" stopColor="#7A3AB0" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
const ZK_BPOISON2_KIMONO = { fill: "url(#zkBPoison2Kimono)", stroke: "#6ADCC8", strokeWidth: 0.7, strokeOpacity: 0.6 };
const ZK_BPOISON2_SLEEVE = { fill: "url(#zkBPoison2Sleeve)", stroke: "#6ADCC8", strokeWidth: 0.7, strokeOpacity: 0.6 };
const ZK_BPOISON2_HAIR = { fill: "url(#zkBPoison2Hair)", stroke: "#6ADCC8", strokeWidth: 0.6, strokeOpacity: 0.55 };
// 蜘蛛の脚。付け根 (x,y)、膝・足首・爪先は付け根からの相対。⚠️ ゆっくり蠢く（付け根で回る）
function ZkBPoison2Leg({ x, y, k, a, t, w = 1, op = 1, d = 0 }) {
  const P = (q) => `${q[0]} ${q[1]}`;
  return (
    <g transform={`translate(${x} ${y})`} opacity={op}><g className="zk-bpoison-creep" style={{ animationDelay: `${d}ms` }}>
      <path d={`M0 0 L${P(k)} L${P(a)} L${P(t)}`} fill="none" stroke="#5ECCB8" strokeWidth={4.2 * w} strokeOpacity="0.6" strokeLinejoin="round" strokeLinecap="round" />
      <path d={`M0 0 L${P(k)}`} stroke="#12383F" strokeWidth={3.6 * w} strokeLinecap="round" />
      <path d={`M${P(k)} L${P(a)}`} stroke="#0E2E35" strokeWidth={2.7 * w} strokeLinecap="round" />
      <path d={`M${P(a)} L${P(t)}`} stroke="#0A262C" strokeWidth={1.7 * w} strokeLinecap="round" />
      <path d={`M${a[0] + (t[0] - a[0]) * 0.7} ${a[1] + (t[1] - a[1]) * 0.7} L${P(t)}`} stroke="#6ADCC8" strokeWidth={0.8 * w} strokeLinecap="round" opacity="0.8" />
      <path d={`M${k[0] * 0.2} ${k[1] * 0.2} L${k[0] * 0.5} ${k[1] * 0.5}`} stroke="#3E8E8A" strokeWidth={0.7 * w} opacity="0.7" strokeLinecap="round" />
      <circle cx={k[0] * 0.28} cy={k[1] * 0.28} r={1.5 * w} fill="url(#zkBPoison2Gold)" />
      <circle cx={k[0]} cy={k[1]} r={1.6 * w} fill="#1E5A60" />
      <circle cx={k[0]} cy={k[1]} r={0.75 * w} fill="#B070E0" />
      <circle cx={a[0]} cy={a[1]} r={1.1 * w} fill="#1E5A60" />
    </g></g>
  );
}
// 糸にぶら下がる小蜘蛛。⚠️ 糸の付け根で揺れる。(x,y)＝糸の付け根、len＝糸の長さ
function ZkBPoison2Dangle({ x, y, len = 14, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y})`}><g className="zk-sway" style={{ animationDelay: `${d}ms` }}>
      <path d={`M0 0 L0 ${len}`} stroke="#DDF4FF" strokeWidth="0.45" opacity="0.85" />
      <g transform={`translate(0 ${len + 2})`}>
        <path d="M-1 -0.6 L-3.6 -2.6 L-4.6 -1 M-1 0 L-4 0 L-5 1.6 M-1 0.6 L-3.4 2.4 L-3.8 4 M1 -0.6 L3.6 -2.6 L4.6 -1 M1 0 L4 0 L5 1.6 M1 0.6 L3.4 2.4 L3.8 4" fill="none" stroke="#0E3036" strokeWidth="0.6" strokeLinecap="round" strokeLinejoin="round" />
        <ellipse cx="0" cy="0.6" rx="1.8" ry="2.4" fill="#15424A" stroke="#6ADCC8" strokeWidth="0.4" strokeOpacity="0.8" />
        <ellipse cx="0" cy="1" rx="0.8" ry="1" fill="#B070E0" />
        <circle cx="0" cy="-2" r="1" fill="#1E5A60" />
      </g>
    </g></g>
  );
}
// 裾の蜘蛛の巣模様
function ZkBPoison2Web({ d }) {
  return <path d={d} fill="none" stroke="#9AE8D8" strokeWidth="0.5" opacity="0.45" />;
}
// 目：切れ長で水色に光る。inner=-1 で目頭が左
function ZkBPoison2Eye({ cx, cy, w = 2.4, far = false, inner = -1, tilt = 0 }) {
  const h = far ? 0.8 : 1.1;
  return (
    <g transform={`translate(${cx} ${cy}) rotate(${tilt}) scale(${-inner} 1)`}>
      <ellipse rx={w + 0.9} ry={h + 0.9} fill="url(#zkBPoison2Mote)" opacity="0.55" />
      <path className="zk-blink" d={`M${-w} ${h * 0.4} Q${-w * 0.1} ${-h * 1.4} ${w} ${-h * 1.1} Q${w * 0.1} ${h * 1.1} ${-w} ${h * 0.4} Z`} fill="#BFF4FF" />
      <circle cx={w * 0.1} cy={-h * 0.1} r={far ? 0.55 : 0.8} fill="#0A2A3A" />
      <path d={`M${-w - 0.2} ${h * 0.4} Q${-w * 0.1} ${-h * 1.4} ${w + 0.8} ${-h * 1.3}`} fill="none" stroke="#0A1418" strokeWidth="0.7" strokeLinecap="round" />
      <path d={`M${-w * 0.4} ${-h * 2.6} Q${w * 0.3} ${-h * 3.1} ${w * 1.1} ${-h * 2.7}`} fill="none" stroke="#1A262C" strokeWidth="0.4" strokeLinecap="round" opacity="0.8" />
    </g>
  );
}
