/* ======================= b3 雲鯨（空を泳ぐ鯨） ======================= */
function ZkBFly3Defs() {
  return (
    <defs>
      <linearGradient id="zkBFly3Body" x1="0.3" y1="0" x2="0.5" y2="1"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.35" stopColor="#D4F2E2" /><stop offset="0.72" stopColor="#6AA898" /><stop offset="1" stopColor="#1E4448" /></linearGradient>
      <linearGradient id="zkBFly3Belly" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#E8FFF0" /><stop offset="1" stopColor="#8AC4B0" /></linearGradient>
      <linearGradient id="zkBFly3Fin" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F4FFF8" /><stop offset="0.5" stopColor="#9ACCB8" /><stop offset="1" stopColor="#2E5A58" /></linearGradient>
      <linearGradient id="zkBFly3Mouth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#0E2A26" /><stop offset="1" stopColor="#041210" /></linearGradient>
      <radialGradient id="zkBFly3Puff" cx="0.4" cy="0.35"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.6" stopColor="#E4F8EC" /><stop offset="1" stopColor="#A8D4C0" /></radialGradient>
      <linearGradient id="zkBFly3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF0B0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <radialGradient id="zkBFly3Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#9AF0B0" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBFly3Aura"><stop offset="0" stopColor="#4AB860" stopOpacity="0.28" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 雲の房（[x,y,r] の円を重ねる）
function ZkBFly3Puffs({ pts, op = 1 }) {
  return (
    <g opacity={op}>
      {pts.map(([x, y, r], i) => <circle key={i} cx={x} cy={y} r={r} fill="url(#zkBFly3Puff)" />)}
    </g>
  );
}
// 鰭から流れる風の筋（流れる破線）
function ZkBFly3Streams({ ds }) {
  return (
    <g fill="none" strokeLinecap="round">
      {ds.map(([d, dl], i) => (
        <g key={i}>
          <path d={d} stroke="#4AB860" strokeWidth="2.2" opacity="0.35" />
          <path d={d} className="zk-bfly-stream" style={{ animationDelay: `${dl}ms` }} stroke="#DFFFE8" strokeWidth="0.9" opacity="0.9" />
        </g>
      ))}
    </g>
  );
}
// 胸鰭（付け根が原点、+x+y 方向へ長く）。金の鰭輪つき
function ZkBFly3Fin({ ring = true }) {
  return (
    <g>
      <path d="M-2 -3 C6 0 14 6 20 13 C22 16 24 19 24 22 C21 21 18 20 16 18 C17 17 16 16 14.6 16 C13 14 11 12 9 11 C9 10 8 9 7 9.4 C4 7 1 5 -3 3 Z" fill="url(#zkBFly3Fin)" {...ZK_BFLY_RIM} />
      <path d="M0 -1 C8 2 15 8 21 16" stroke="#FFFFFF" strokeWidth="0.8" opacity="0.7" fill="none" strokeLinecap="round" />
      {ring && <path d="M3.6 -2.4 C5.6 0 5.4 3 3.4 5.4 L5.6 6.4 C7.8 3.6 8 0 5.8 -2.8 Z" fill="url(#zkBFly3Gold)" />}
    </g>
  );
}
// 尾鰭（付け根が原点、左右に広がる）
function ZkBFly3Flukes() {
  return (
    <g>
      <path d="M0 0 C-4 -3 -10 -6 -17 -5 C-15 -2 -12 1 -8 2.6 C-5 3.6 -2 3.4 0 2.6 C2 3.4 5 3.6 8 2.6 C12 1 15 -2 17 -5 C10 -6 4 -3 0 0 Z" fill="url(#zkBFly3Fin)" {...ZK_BFLY_RIM} />
      <path d="M-15 -4.4 C-10 -4.6 -5 -2.6 0 0.4 C5 -2.6 10 -4.6 15 -4.4" stroke="#FFFFFF" strokeWidth="0.7" opacity="0.7" fill="none" />
    </g>
  );
}
