/* ---- /zk:fly ---- */
/* ---- zk:bug ---- */
// ZKT/boss_bug.jsx — むし 区分ボス（系統 wind）：大鍬形・女王蟻・土蜘蛛
// 深い緑の甲に若緑の縁、翡翠の目。格の印は金（鍬形の大顎の縁と胸の縁・女王の冠と腰の輪・土蜘蛛の角と脚の輪）。
/* ---- 共有の小物 ---- */
const ZK_BBUG_RIM = { stroke: "#6AD880", strokeWidth: 0.7, strokeOpacity: 0.65, strokeLinejoin: "round" };
// 漂う風の光
function ZkBBugMotes({ pts, fill }) {
  return (
    <g>
      {pts.map(([x, y, r, d], i) => (
        <g key={i} transform={`translate(${x} ${y})`}><g className="zk-bob" style={{ animationDelay: `${d}ms` }}><circle r={r} fill={fill} /></g></g>
      ))}
    </g>
  );
}
// 風の筋
function ZkBBugGusts({ pts }) {
  return (
    <g>
      {pts.map(([x, y, w, d], i) => (
        <g key={i} className="zk-gust" style={{ animationDelay: `${d}ms` }}>
          <path d={`M${x} ${y} Q${x + w / 2} ${y - 3} ${x + w} ${y}`} fill="none" stroke="#DFFFE8" strokeWidth="0.7" opacity="0.55" strokeLinecap="round" />
        </g>
      ))}
    </g>
  );
}
// 節のある脚（d は折れ線）。stripe=縞、hair=剛毛
function ZkBBugLeg({ d, w = 2.4, fill = "#10261A", hi = "#7AD890", stripe, hair, op = 1 }) {
  return (
    <g opacity={op}>
      <path d={d} fill="none" stroke="#6AD880" strokeWidth={w + 1.1} strokeOpacity="0.5" strokeLinecap="round" strokeLinejoin="round" />
      {hair && <path d={d} fill="none" stroke={fill} strokeWidth={w + 1.8} strokeDasharray="0.3 1.2" strokeLinejoin="round" opacity="0.85" />}
      <path d={d} fill="none" stroke={fill} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
      {stripe && <path d={d} fill="none" stroke={stripe} strokeWidth={w * 0.9} strokeDasharray="3.6 2.6" strokeLinejoin="round" opacity="0.7" />}
      <path d={d} fill="none" stroke={hi} strokeWidth={w * 0.28} strokeLinecap="round" strokeLinejoin="round" opacity="0.5" transform="translate(-0.3 -0.45)" />
    </g>
  );
}
// 光る目（中心 x,y、幅 w、傾き r）。切れ長で鋭い翡翠。
function ZkBBugEye({ x, y, w = 2.6, h = 1.4, r = 0, glow, d = "0ms", pupil = true }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r})`}>
      <ellipse rx={w * 1.7} ry={w * 1.2} fill={`url(#${glow})`} opacity="0.85" />
      <g className="zk-blink" style={{ animationDelay: d }}>
        <path d={`M${-w} ${h * 0.3} Q${-w * 0.1} ${-h * 1.3} ${w} ${-h * 0.3} Q${w * 0.1} ${h} ${-w} ${h * 0.3} Z`} fill="#B8FFD0" />
        {pupil && <ellipse cx={-w * 0.15} cy={-h * 0.05} rx={w * 0.2} ry={h * 0.6} fill="#04140A" />}
      </g>
    </g>
  );
}

/* ================= 1. 大鍬形（b1）：金縁の大顎を振りかざす群れの親分 ================= */
function ZkBBug1Defs() {
  return (
    <defs>
      <linearGradient id="zkBBug1Shell" x1="0.15" y1="0" x2="0.75" y2="1"><stop offset="0" stopColor="#9AE8B0" /><stop offset="0.28" stopColor="#2E7A4E" /><stop offset="0.65" stopColor="#0E2A1C" /><stop offset="1" stopColor="#040C07" /></linearGradient>
      <linearGradient id="zkBBug1Pro" x1="0.2" y1="0" x2="0.8" y2="1"><stop offset="0" stopColor="#7AC894" /><stop offset="0.45" stopColor="#1E4A32" /><stop offset="1" stopColor="#050E08" /></linearGradient>
      <linearGradient id="zkBBug1Mand" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#6A5A34" /><stop offset="0.45" stopColor="#2A2414" /><stop offset="1" stopColor="#0A0804" /></linearGradient>
      <linearGradient id="zkBBug1Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF4C0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBBug1Wing" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stopColor="#EFFFF4" stopOpacity="0.7" /><stop offset="1" stopColor="#9AF0B0" stopOpacity="0.2" /></linearGradient>
      <radialGradient id="zkBBug1Glow"><stop offset="0" stopColor="#B8FFD0" stopOpacity="0.9" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBBug1Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#B8FFC8" /><stop offset="1" stopColor="#4AB860" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 大顎：根元(0,0)から左上へ反り、先が鉤に。金の縁。⚠️ 根元を軸に開閉
function ZkBBug1Mandible({ cls = "zk-bbug-pinch", d = 0, dark = false }) {
  return (
    <g className={cls} style={{ animationDelay: `${d}ms` }}>
      <path d="M-4 0 C-6.4 -10 -6.6 -20 -3.4 -27.6 C-1.4 -32 2.6 -34.2 6.4 -33 C3.4 -31.2 1.4 -28.4 0.8 -25.4 L3.6 -24.2 L0.9 -21.4 C1 -16.6 1.4 -12.6 2 -9.6 L4.8 -9.4 L2.6 -6.4 C3 -3.6 3.6 -1.4 4.2 0.4 Z"
        fill="url(#zkBBug1Mand)" stroke="url(#zkBBug1Gold)" strokeWidth="1.1" strokeLinejoin="round" opacity={dark ? 0.85 : 1} />
      <path d="M-2.6 -2 C-4.4 -11 -4.4 -19 -2 -26 C-0.6 -29.4 1.6 -31.2 4 -32" fill="none" stroke="#FFF0B0" strokeWidth="0.7" opacity="0.6" strokeLinecap="round" />
    </g>
  );
}
function ZkBBug1Wing({ x, y, s = 1, d = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s})`}><g className="zk-wing" style={{ animationDelay: `${d}ms` }}>
      <path d="M0 0 C6 -12 16 -20 27 -23 C26 -16 22 -9 16 -4 C11 0 5 2 0 2.4 Z" fill="url(#zkBBug1Wing)" stroke="#9AF0B0" strokeWidth="0.5" strokeOpacity="0.8" />
      <path d="M2 0 C9 -8 16 -14 24 -20 M4 1 C10 -3 15 -7 19 -11" fill="none" stroke="#DFFFE8" strokeWidth="0.4" opacity="0.6" />
    </g></g>
  );
}
