      <ZkBFightMotes fill="url(#zkBFight2Mote)" pts={[[12, 34, 2, -400], [88, 50, 2.2, -1500], [86, 76, 1.6, 0], [26, 16, 1.4, -2200], [12, 64, 1.6, -1000]]} />
