        <path d="M54 30 C60 28 66 31 66 37 C62 38 58 38 55 37 Z" fill="url(#zkBFight3Plate)" stroke="url(#zkBFight3Gold)" strokeWidth="1" />
        {/* 腰の垂れ */}
