        <ZkBFight3Bracer x={54.6} y={55} w={6.4} r={40} />
        {/* 頭（斜め） */}
        <g transform="translate(46 22) rotate(-6) scale(0.95)"><ZkBFight3HeadFront q={1} /></g>
        {/* 剣：両手で斜めに立てて構える */}
