        {/* 遠い耳（向かって左、細く） */}
        <g transform="translate(29 30) scale(-0.45 0.9)"><ZkBNormal3Ear s={1.1} d={-900} /></g>
        {/* 頭 */}
        <g transform="translate(40 42) rotate(-6) scale(1.2)"><ZkBNormal3HeadFront q={1} /></g>
        {/* 鼻：高く掲げる */}
        <g transform="translate(34 56) rotate(-28)"><ZkBNormal3Trunk s={1.02} d={-600} /></g>
