      <g transform="translate(58.6 46.4)"><g className="zk-bghost-neck" style={{ animationDelay: "-1200ms" }}><g transform="translate(-58.6 -46.4)">
        <ZkBGhost1Neck segs={["M58.6 46.4 C62 38 60 30 54 26 C46 20 48 10 58 10", "M58 10 C68 10 72 20 66 28 C60 36 50 40 42 45 C37 48 32 50 27 49"]} />
        <g transform="translate(26 38) rotate(16) scale(1.06)"><ZkBGhost1HeadFront q={1} /></g>
      </g></g></g>
