      <path d="M-19 -8.4 C-12 -7.6 -5 -6.4 0 -4 C5 -6.4 12 -7.6 19 -8.4" fill="none" stroke="url(#zkBGhost2Gold)" strokeWidth="1.1" strokeLinecap="round" transform={q ? "translate(-1 0) scale(0.94 1)" : undefined} />
