/* ================= 3. 砂時計の番人（b3）：黒曜の魔像、胸に金枠の大砂時計、菫の砂 ================= */
function ZkBPsychic3Defs() {
  return (
    <defs>
      <linearGradient id="zkBPsychic3Stone" x1="0.15" y1="0" x2="0.85" y2="1"><stop offset="0" stopColor="#8070A8" /><stop offset="0.45" stopColor="#3A2C5C" /><stop offset="1" stopColor="#120A20" /></linearGradient>
      <linearGradient id="zkBPsychic3Far" x1="0.15" y1="0" x2="0.85" y2="1"><stop offset="0" stopColor="#4A3C6C" /><stop offset="1" stopColor="#0E0818" /></linearGradient>
      <linearGradient id="zkBPsychic3Gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#FFF4C0" /><stop offset="0.5" stopColor="#E8C46A" /><stop offset="1" stopColor="#9A7020" /></linearGradient>
      <linearGradient id="zkBPsychic3Glass" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#D8C0FF" stopOpacity="0.45" /><stop offset="0.5" stopColor="#6A4A9A" stopOpacity="0.2" /><stop offset="1" stopColor="#E0D0FF" stopOpacity="0.4" /></linearGradient>
      <linearGradient id="zkBPsychic3Sand" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#F4E0FF" /><stop offset="0.5" stopColor="#B070F0" /><stop offset="1" stopColor="#6A28B0" /></linearGradient>
      <linearGradient id="zkBPsychic3Cloth" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#5A3A8A" /><stop offset="1" stopColor="#140824" /></linearGradient>
      <radialGradient id="zkBPsychic3Core"><stop offset="0" stopColor="#E8C8FF" stopOpacity="0.9" /><stop offset="1" stopColor="#6A3A9A" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBPsychic3Glow"><stop offset="0" stopColor="#E8D0FF" stopOpacity="0.95" /><stop offset="1" stopColor="#6A3A9A" stopOpacity="0" /></radialGradient>
      <radialGradient id="zkBPsychic3Mote"><stop offset="0" stopColor="#FFFFFF" /><stop offset="0.4" stopColor="#D8B0FF" /><stop offset="1" stopColor="#8A5AC8" stopOpacity="0" /></radialGradient>
    </defs>
  );
}
// 胸の大砂時計（原点＝くびれ）。⚠️ 砂が落ちる
function ZkBPsychic3Glass({ x, y, s = 1, sx = 1 }) {
  return (
    <g transform={`translate(${x} ${y}) scale(${s * sx} ${s})`}>
      <path d="M-13 -17 L13 -17 L13 17 L-13 17 Z" fill="#0A0414" />
      <g className="zk-shine"><ellipse rx="14" ry="17" fill="url(#zkBPsychic3Core)" /></g>
      <path d="M-10 -15 C-10 -7 -2 -3 -1.2 0 C-2 3 -10 7 -10 15 L10 15 C10 7 2 3 1.2 0 C2 -3 10 -7 10 -15 Z" fill="url(#zkBPsychic3Glass)" stroke="#E8D8FF" strokeWidth="0.5" strokeOpacity="0.7" />
      <path d="M-8.2 -7.4 C-5.6 -4.4 -2 -2 -1.1 0 L1.1 0 C2 -2 5.6 -4.4 8.2 -7.4 C4 -8.6 -4 -8.6 -8.2 -7.4 Z" fill="url(#zkBPsychic3Sand)" />
      <path d="M-9.6 15 C-8 11 -3 7.4 0 6.6 C3 7.4 8 11 9.6 15 Z" fill="url(#zkBPsychic3Sand)" />
      <path d="M0 0 L0 7" stroke="#F4E0FF" strokeWidth="0.7" />
      {[0, -600, -1200].map((dl, i) => (<g key={i} className="zk-bpsychic-sand" style={{ animationDelay: `${dl}ms` }}><circle cx="0" cy="0.4" r="0.6" fill="#FFFFFF" /></g>))}
      <path d="M-8 -13 C-8 -9 -5.6 -6 -3.4 -3.6" fill="none" stroke="#FFFFFF" strokeWidth="0.8" opacity="0.55" strokeLinecap="round" />
      {/* 金の枠 */}
      <path d="M-15 -20 L15 -20 L13 -15 L-13 -15 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" />
      <path d="M-15 20 L15 20 L13 15 L-13 15 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" />
      <path d="M-12.2 -15 L-11.6 15 M12.2 -15 L11.6 15" stroke="url(#zkBPsychic3Gold)" strokeWidth="1.8" />
      <path d="M-12.2 -2 L-9.4 0 L-12.2 2 M12.2 -2 L9.4 0 L12.2 2" fill="none" stroke="url(#zkBPsychic3Gold)" strokeWidth="0.9" />
      <path d="M-4 -17.6 L0 -19 L4 -17.6 M-4 17.6 L0 19 L4 17.6" fill="none" stroke="#6A4A10" strokeWidth="0.5" />
    </g>
  );
}
// 太い岩の肢：a→b、幅 wa→wb
function ZkBPsychic3Limb({ a, b, wa, wb, far = false }) {
  const dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l, ny = dx / l;
  const p = [[a[0] + nx * wa / 2, a[1] + ny * wa / 2], [b[0] + nx * wb / 2, b[1] + ny * wb / 2], [b[0] - nx * wb / 2, b[1] - ny * wb / 2], [a[0] - nx * wa / 2, a[1] - ny * wa / 2]];
  return <path d={ZK_BPSYCHIC_D(p)} fill={far ? "url(#zkBPsychic3Far)" : "url(#zkBPsychic3Stone)"} {...ZK_BPSYCHIC_RIM} />;
}
function ZkBPsychic3Joint({ x, y, r = 3.4, far = false }) {
  return (
    <g>
      <circle cx={x} cy={y} r={r} fill={far ? "#1A1028" : "#2A1E44"} {...ZK_BPSYCHIC_RIM} />
      <circle cx={x} cy={y} r={r * 0.28} fill="#B070F0" opacity="0.6" />
    </g>
  );
}
// 拳（手首が +y）。金の腕輪つき
function ZkBPsychic3Fist({ x, y, r = 0, s = 1, far = false }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
      <path d="M-5.8 -4 C-5.8 -6 -4.2 -6.8 -2.2 -6.8 L4 -6.8 C5.8 -6.8 6.4 -5.4 6.4 -3.6 L6.4 3.6 C6.4 5.6 5.2 6.4 3.2 6.4 L-3.8 6.4 C-5.2 6.4 -5.8 5.4 -5.8 3.8 Z" fill={far ? "url(#zkBPsychic3Far)" : "url(#zkBPsychic3Stone)"} {...ZK_BPSYCHIC_RIM} />
      <path d="M-2.4 -6.6 L-2.4 -1.6 M0.9 -6.6 L0.9 -1.6 M3.9 -6.6 L3.9 -1.6" stroke="#0E0818" strokeWidth="0.6" />
      <path d="M-5.8 -0.6 C-3 -1.6 -0.6 -0.4 1 1.8 L-4 4 Z" fill="#6A5A90" opacity="0.8" />
      <path d="M-5.4 6.4 L5.8 6.4 L5.2 9.4 L-4.8 9.4 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" />
      <circle cx="0.2" cy="7.9" r="0.9" fill="#C890FF" />
    </g>
  );
}
// 刻まれた光の溝
function ZkBPsychic3Grooves({ d }) {
  return <g className="zk-shine"><path d={d} fill="none" stroke="#B888FF" strokeWidth="0.6" opacity="0.7" strokeLinecap="round" strokeLinejoin="round" /></g>;
}
// 兜の頭（古い仮面の顔、金の反り角）。原点＝顔の中心、q で左へ寄せる
function ZkBPsychic3Head({ x, y, r = 0, s = 1, q = 0 }) {
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
      <path d="M5.6 -3 C10.6 -4 14.6 -8 15.6 -13.4 C12.6 -11.6 10.6 -12 9 -13.6 C8.6 -10 6 -8.6 2.6 -7.4 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" transform={q ? "translate(1.6 -1.2) scale(0.8)" : undefined} />
      <path d="M-8 5 C-9 -3 -6 -9 0 -9.6 C6 -9 9 -3 8 5 L5 9 C2 10.6 -2 10.6 -5 9 Z" fill="url(#zkBPsychic3Stone)" {...ZK_BPSYCHIC_RIM} />
      <path d="M-5.6 -3 C-10.6 -4 -14.6 -8 -15.6 -13.4 C-12.6 -11.6 -10.6 -12 -9 -13.6 C-8.6 -10 -6 -8.6 -2.6 -7.4 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" />
      <path d="M-5 -6.6 C-2 -8.6 2 -8.6 4 -7.6" fill="none" stroke="#C8B8F0" strokeWidth="0.8" opacity="0.55" strokeLinecap="round" />
      <path d={`M${-5.6 + q} 0.6 C${-2 + q} -0.6 ${2 + q} -0.6 ${5.6 + q * 0.6} 0.6 L${5 + q * 0.6} 5 C${3 + q} 8.2 ${-3 + q} 8.2 ${-5 + q} 5 Z`} fill="#4E3E74" stroke="#0E0818" strokeWidth="0.4" />
      <path d="M-8.2 -1.6 C-4 -3.8 4 -3.8 8.2 -1.6 L8 0.6 C4 -1.4 -4 -1.4 -8 0.6 Z" fill="url(#zkBPsychic3Gold)" stroke="#6A4A10" strokeWidth="0.3" />
      <path d={`M${q} -4 L${1.2 + q} -2.6 L${q} -1.4 L${-1.2 + q} -2.6 Z`} fill="#C890FF" stroke="#FFF0C0" strokeWidth="0.3" />
      <path d={`M${-5 + q} 1.2 L${-1 + q} 1.6 L${-1.4 + q} 3.2 L${-4.6 + q} 2.8 Z M${1 + q} 1.6 L${5 + q * 0.6} 1.2 L${4.6 + q * 0.6} 2.8 L${1.4 + q} 3.2 Z`} fill="#0A0414" />
      <ZkBPsychicEye x={-3 + q} y={2.2} w={1.7} h={0.9} r={8} glow="zkBPsychic3Glow" pupil={false} />
      <ZkBPsychicEye x={3 + q * 0.8} y={2.2} w={q ? 1.3 : 1.7} h={0.9} r={-8} glow="zkBPsychic3Glow" pupil={false} d="-100ms" />
      <path d={`M${q} 3.4 L${q + 0.2} 5.4 M${-2 + q} 6.6 L${2 + q} 6.6`} stroke="#0E0818" strokeWidth="0.5" strokeLinecap="round" />
    </g>
  );
}
// 背の外套（ぼろの裾）
