        <path className="em-pillar in" d="M24 46 C16 42 17 30 21 22 C22 26 23 26 24 22 C25 30 30 34 29 40 C28 44 26 46 24 46 Z" fill="#FFE070" />
        {[0, 1, 2, 3, 4].map((k) => <circle key={k} className={`em-ember e${k}`} cx={14 + k * 5} cy="30" r="1.8" fill="#FFD070" />)}
