                <path key={j} d={`M0 ${24 + o} C16 ${16 + o} 32 ${16 + o} 48 ${24 + o} C32 ${20.5 + o} 16 ${20.5 + o} 0 ${24 + o} Z`}
                  fill={k === 2 ? "#FFF3D6" : "#FFC0A0"} stroke="#FF3A4A" strokeWidth="1" />
